NAME = 'SloKJV: Slovenian translation of Holy Bible King James Version (1769)'
BOOK = 'Leviticus'

CHAPTERS = {
    1: {
        1: 'Gospod je zaklical k Mojzesu in mu spregovoril iz šotorskega svetišča skupnosti, rekoč:',
        2: '»Spregovori Izraelovim otrokom in jim reci: ›Če katerikoli človek izmed vas prinese dar Gospodu, boste prinesli svojo daritev izmed živine, od tropa in od črede.',
        3: 'Če bo njegov dar žgalna daritev od črede, naj daruje samca brez pomanjkljivosti. Daroval ga bo iz svoje lastne prostovoljne volje pri vratih šotorskega svetišča skupnosti pred Gospodom.',
        4: 'Svojo roko bo položil na glavo žgalne daritve in ta bo sprejeta zanj, da opravi spravo zanj.',
        5: 'Bikca bo zaklal pred Gospodom in duhovniki, Aronovi sinovi, bodo prinesli kri in kri poškropili naokoli nad oltarjem, ki je pri vratih šotorskega svetišča skupnosti.',
        6: 'Žgalno daritev bo odrl in jo razrezal na koščke.',
        7: 'Sinovi duhovnika Arona bodo na oltar položili ogenj in po vrsti na ogenj položili les.',
        8: 'Duhovniki, Aronovi sinovi, bodo položili dele, glavo in tolščo, po vrsti na les, ki je na ognju, ki je na oltarju,',
        9: 'toda njegovo drobovino in njegove noge bo umil v vodi. Duhovnik bo vse sežgal na oltarju, da bo žgalna daritev, ognjena daritev, prijetnega vonja Gospodu.',
        10: 'Če bo njegov dar za žgalno daritev od tropov, namreč od ovc ali od koz, bo privedel samca brez pomanjkljivosti.',
        11: 'Zaklal ga bo na severni strani oltarja pred Gospodom. Duhovniki, Aronovi sinovi, bodo njegovo kri poškropili naokoli nad oltarjem.',
        12: 'Razrezal ga bo na koščke, z njegovo glavo in njegovo tolščo. Duhovnik jih bo po vrsti položil na les, ki je na ognju, ki je na oltarju,',
        13: 'toda drobovje in noge bo umil z vodo. Duhovnik bo vse to prinesel in to sežgal na oltarju. To je žgalna daritev, ognjena daritev, prijetnega vonja Gospodu.',
        14: 'Če bo žgalna daritev za njegov dar Gospodu od perjadi, potem bo svojo daritev prinesel od grlic ali od mladih golobov.',
        15: 'Duhovnik bo to prinesel na oltar in ji odščipnil vrat in jo sežgal na oltarju; in njena kri bo iztisnjena ob strani oltarja.',
        16: 'Njeno golšo bo odtrgal z njenimi peresi in jo odvrgel na vzhodnem delu, poleg oltarja, ob kraju za pepel',
        17: 'in nalomi jo s perutmi, toda ne bo je ločil narazen. Duhovnik bo to sežgal na oltarju, na lesu, ki je na ognju. To je žgalna daritev, ognjena daritev, prijetnega vonja Gospodu.‹«',
    },
    2: {
        1: '»›Ko bo kdorkoli daroval jedilno daritev Gospodu, bo njegov dar iz fine moke in na to bo izlil olje in položil kadilo.',
        2: 'To bo prinesel Aronovim sinovom, duhovnikom. Iz od tega bo zajel prgišče moke in od olja, z vsem kadilom in duhovnik bo to sežgal na oltarju v spomin na to, da bo ognjena daritev, prijeten vonj Gospodu.',
        3: 'Ostanek jedilne daritve bo od Arona in njegovih sinov. To je najsvetejša stvar Gospodovih daritev, narejenih z ognjem.',
        4: 'Če prineseš dar jedilne daritve, spečen v peči, naj bodo to nekvašeni kolači iz fine moke, pomazani z oljem ali nekvašeni vaflji, pomazani z oljem.',
        5: 'Če bo tvoj dar jedilna daritev, spečena v ponvi, naj bo ta iz fine nekvašene moke, umešane z oljem.',
        6: 'Razdelil jo boš na koščke in nanjo izlil olje. To je jedilna daritev.',
        7: 'Če bo tvoj dar jedilna daritev, spečena v tvoji ponvi za cvrtje, naj bo narejena iz fine moke z oljem.',
        8: 'Jedilno daritev, ki je narejena iz teh stvari, boš prinesel Gospodu in ko je ta izročena duhovniku, jo bo prinesel na oltar.',
        9: 'Duhovnik bo vzel od jedilne daritve njegov spomin in tega bo sežgal na oltarju. To je ognjena daritev, prijetnega vonja Gospodu.',
        10: 'To, kar je ostalo od jedilne daritve, bo od Arona in njegovih sinov. To je najsvetejša stvar Gospodovih daritev, narejenih z ognjem.',
        11: 'Nobena jedilna daritev, ki jo boste prinesli h Gospodu, naj ne bo pripravljena s kvasom, kajti nobenega kvasa niti nobenega medu ne boste sežgali pri vsaki Gospodovi daritvi, narejeni z ognjem.',
        12: 'Kar se tiče daru prvih sadov, jih boste darovali Gospodu, toda ne bodo sežgani na oltarju za prijeten vonj.',
        13: 'Vsak dar svoje jedilne daritve boš začinil s soljo; niti ne boš trpel, da bi sol zaveze tvojega Boga manjkala pri tvoji jedilni daritvi. Z vsemi svojimi darovi boš daroval sol.',
        14: 'Če daruješ jedilno daritev svojih prvih sadov Gospodu, boš daroval za jedilno daritev svojih prvih sadov zeleno žitno klasje, posušeno ob ognju, torej žito, omlateno iz polnih klasov.',
        15: 'Nanj boš izlil olje in nanj dal kadilo. To je jedilna daritev.',
        16: 'Duhovnik bo sežgal spomin od tega, del od stolčenega žita in del od njegovega olja, z vsem njegovim kadilom. To je ognjena daritev Gospodu.',
    },
    3: {
        1: 'Če bo njegov dar darovanje mirovne daritve, če jo bo daroval od črede; bodisi je ta samec ali samica, jo bo daroval brez pomanjkljivosti pred Gospodom.',
        2: 'Svojo roko bo položil na glavo njegovega daru in ga zaklal pri vratih šotorskega svetišča skupnosti. Aronovi sinovi, duhovniki, pa bodo kri poškropili naokoli po oltarju.',
        3: 'Daroval bo dar mirovne daritve, ognjeno daritev Gospodu; tolščo, ki pokriva drobovje in vso tolščo, ki je na drobovju.',
        4: 'In obe ledvici in tolščo, ki je na njiju, ki je ob bokih in opno nad jetri, z ledvicama, bo odstranil.',
        5: 'Aronovi sinovi bodo to sežgali na oltarju nad žgalno daritvijo, ki je na lesu, to je na ognju. To je ognjena daritev, prijetnega vonja Gospodu.',
        6: 'Če bo njegov dar za darovanje mirovne daritve Gospodu od tropa; samec ali samica, ga bo daroval brez pomanjkljivosti.',
        7: 'Če daruje jagnje za njegov dar, potem ga bo daroval pred Gospodom.',
        8: 'Svojo roko bo položil na glavo svojega daru in ga zaklal pred šotorskim svetiščem skupnosti, Aronovi sinovi pa bodo njegovo kri poškropili naokoli nad oltarjem.',
        9: 'Daroval bo od žrtvovanja mirovne daritve, ognjeno daritev Gospodu; njegovo tolščo in celoten tolsti rep; odrezal ga bo tik ob hrbtenici; in tolščo, ki pokriva drobovje in vso tolščo, ki je na drobovju',
        10: 'in obe ledvici in tolščo, ki je na njiju, ki je ob bokih in opno nad jetri, z ledvicama; to bo vzel stran.',
        11: 'Duhovnik bo to sežgal na oltarju. To to je hrana darovanja, ognjena daritev Gospodu.',
        12: 'Če bo njegov dar kozel, potem ga bo daroval pred Gospodom.',
        13: 'Svojo roko bo položil na njegovo glavo in ga zaklal pred šotorskim svetiščem skupnosti, Aronovi sinovi pa bodo njegovo kri poškropili naokoli po oltarju.',
        14: 'Od tega bo daroval svoj dar, ognjeno daritev Gospodu; tolščo, ki pokriva drobovje in vso tolščo, ki je na drobovju.',
        15: 'In obe ledvici in tolščo, ki je na njiju, ki je ob bokih in opno nad jetri, z ledvicama, to bo vzeto proč.',
        16: 'Duhovnik jih bo sežgal na oltarju. To je hrana ognjene daritve za prijeten vonj. Vsa tolšča je Gospodova.',
        17: 'To bo večen zakon za vaše rodove po vseh vaših prebivališčih, da ne jeste niti tolšče niti krvi.‹«',
    },
    4: {
        1: 'Gospod je spregovoril Mojzesu, rekoč:',
        2: '»Govori Izraelovim otrokom, rekoč: ›Če bo duša zaradi nevednosti grešila zoper katerekoli izmed Gospodovih zapovedi, glede stvari, ki se ne bi smele storiti, in bo storila zoper katerokoli izmed njih;',
        3: 'če duhovnik, ki je maziljen, stori greh glede na greh ljudstva, potem naj za svoj greh, ki ga je zagrešil, privede mladega bikca brez pomanjkljivosti Gospodu za daritev za greh.',
        4: 'Bikca bo privedel k vratom šotorskega svetišča skupnosti pred Gospoda in svojo roko bo položil bikcu na glavo in pred Gospodom bo bikca zaklal.',
        5: 'Duhovnik, ki je maziljen, bo vzel od krvi bikca in jo prinesel do šotorskega svetišča skupnosti',
        6: 'in duhovnik bo svoj prst pomočil v kri in pred zagrinjalom svetišča kri sedemkrat poškropil pred Gospodom.',
        7: 'Duhovnik bo nekaj krvi dal na rogove oltarja prijetnega vonja pred Gospodom, ki je v šotorskem svetišču skupnosti; in vso kri bikca bo izlil ob vznožju oltarja žgalne daritve, ki je ob vratih šotorskega svetišča skupnosti.',
        8: 'Iz njega bo vzel vso tolščo bikca za daritev za greh; tolščo, ki pokriva drobovje in vso tolščo, ki je na drobovju,',
        9: 'dve ledvici in tolščo, ki je na njiju, ki je ob bokih in opno nad jetri, z ledvicama, to bo vzeto proč,',
        10: 'kot je bilo vzeto od bikca žrtvovanja mirovnih daritev. Duhovnik jih bo sežgal na oltarju žgalne daritve.',
        11: 'In kožo bikca in vse njegovo meso z njegovo glavo, z njegovimi nogami, njegovim drobovjem in njegovim iztrebkom.',
        12: 'Celo celotnega bikca bo odnesel naprej, zunaj tabora, na čist prostor, kjer je bil izsut pepel in ga z ognjem sežgal na lesu. Sežgan bo kjer je izsut pepel.',
        13: 'Če celotna Izraelova skupnost greši zaradi nevednosti in bo stvar skrita pred očmi zbora in so storili nekaj zoper katerokoli izmed Gospodovih zapovedi glede stvari, ki ne bi smele biti storjene in so krivi;',
        14: 'ko je greh, ki so ga zagrešili zoper njega znan, potem bo skupnost darovala mladega bikca za greh in ga privedla pred šotorsko svetišče skupnosti.',
        15: 'Starešine skupnosti bodo pred Gospodom svoje roke položili na glavo bikca in bikec bo zaklan pred Gospodom.',
        16: 'Duhovnik, ki je maziljen, bo k šotorskemu svetišču skupnosti prinesel od krvi bikca',
        17: 'in duhovnik bo svoj prst pomočil v nekaj od krvi in jo sedemkrat poškropil pred Gospodom, torej pred zagrinjalom.',
        18: 'Nekaj krvi bo dal na rogove oltarja, ki je pred Gospodom, to je v šotorskem svetišču skupnosti in vso kri bo izlil ob vznožju oltarja žgalne daritve, ki je ob vratih šotorskega svetišča skupnosti.',
        19: 'Iz njega bo vzel vso njegovo tolščo in jo sežgal na oltarju.',
        20: 'Z bikcem bo storil kakor je storil z bikcem daritve za greh; tako bo storil s tem. In duhovnik bo zanje opravil spravo in to jim bo odpuščeno.',
        21: 'Bikca bo odnesel zunaj tabora in ga sežgal kakor je sežgal prvega bikca. To je daritev za greh za skupnost.',
        22: 'Ko je voditelj grešil in storil nekaj zaradi nevednosti zoper katerokoli izmed zapovedi Gospoda, svojega Boga, glede stvari, ki naj ne bi bile storjene in je kriv,',
        23: 'ali če njegov greh, v čemer je grešil, pride k njegovemu spoznanju; bo prinesel svoj dar, kozlička izmed koz, samca brez pomanjkljivosti.',
        24: 'Svojo roko bo položil na glavo kozla in ga zaklal na kraju, kjer koljejo žgalno daritev pred Gospodom. To je daritev za greh.',
        25: 'Duhovnik bo s svojim prstom vzel od krvi daritve za greh in to dal na rogove oltarja žgalne daritve in njegovo kri bo izlil ob vznožju oltarja žgalne daritve.',
        26: 'Vso njegovo tolščo bo sežgal na oltarju, kakor tolščo žrtvovanja mirovnih daritev. Duhovnik bo zanj opravil spravo, glede na njegov greh in ta mu bo odpuščen.',
        27: 'Če kdorkoli izmed preprostega ljudstva greši zaradi nevednosti, medtem ko stori nekaj zoper katerokoli izmed Gospodovih zapovedi, glede stvari, ki ne bi smele biti storjene in je kriv;',
        28: 'ali če njegov greh, ki ga je zagrešil, pride v njegovo spoznanje; potem bo za svoj greh, ki ga je zagrešil, prinesel svoj dar, kozlička od koz, samico brez pomanjkljivosti.',
        29: 'Svojo roko bo položil na glavo daritve za greh in na kraju žgalne daritve bo zaklal daritev za greh.',
        30: 'Duhovnik bo s prstom vzel od njegove krvi in to dal na rogove oltarja žgalne daritve in vso njegovo kri bo izlil ob vznožju oltarja.',
        31: 'Odvzel bo vso njegovo tolščo, kakor je odvzeta tolšča žrtvovanja mirovnih daritev, in duhovnik jo bo sežgal na oltarju v prijeten vonj Gospodu, in duhovnik bo zanj opravil spravo in to mu bo odpuščeno.',
        32: 'Če privede jagnje v dar za greh, bo prinesel samico, brez pomanjkljivosti.',
        33: 'Svojo roko bo položil na glavo daritve za greh in jo na kraju, kjer koljejo žgalno daritev, zaklal v daritev za greh.',
        34: 'Duhovnik bo s svojim prstom vzel od krvi daritve za greh in to dal na rogove oltarja žgalne daritve in vso kri izlil ob vznožju oltarja.',
        35: 'Odvzel bo vso njeno tolščo, kakor je tolšča jagnjeta odvzeta od žrtvovanja mirovnih daritev, in duhovnik jih bo sežgal na oltarju, glede na daritve, narejene z ognjem Gospodu, in duhovnik bo opravil spravo za njegov greh, ki ga je zagrešil in ta mu bo odpuščen.',
    },
    5: {
        1: 'Če duša greši in sliši glas priseganja in je priča, bodisi da je to videla ali izvedela o tem; če tega ne izusti, potem bo nosila svojo krivičnost.',
        2: 'Ali če se duša dotakne katerekoli nečiste stvari, bodisi je to truplo nečiste živali ali truplo nečiste živine ali truplo nečistih plazečih bitij, in če je to skrito pred njim, bo tudi on nečist in kriv.',
        3: 'Ali če se on dotakne nečistosti človeka, kakršnakoli nečistost je to, da se bo človek z njo omadeževal in je to skrito pred njim; potem bo kriv, ko izve o tem.',
        4: 'Ali če duša priseže, razglašujoč s svojimi ustnicami, da stori zlo ali da stori dobro, karkoli je to, kar bo človek s prisego razglasil in bo to skrito pred njim; ko izve o tem, potem bo kriv v eni izmed teh.',
        5: 'Zgodilo se bo, ko bo kriv v eni izmed teh stvari, da bo priznal, da je v tej stvari grešil.',
        6: 'Za svoj greh, ki ga je zagrešil, bo prinesel Gospodu svojo daritev za prestopek, samico izmed tropa, jagnje ali kozlička izmed koz za daritev za greh; in duhovnik bo zanj opravil spravo glede njegovega greha.',
        7: 'Če pa ne bo zmožen prinesti jagnjeta, potem bo za svoj prekršek, ki ga je zagrešil, Gospodu prinesel dve grlici ali dva mlada goloba, enega za daritev za greh in drugega za žgalno daritev.',
        8: 'Prinesel ju bo duhovniku, ki bo najprej daroval to, kar je za daritev za greh in njegovo glavo bo odščipnil od vratu, toda tega ne bo ločil narazen.',
        9: 'Poškropil bo od krvi daritve za greh na strani oltarja. Preostanek krvi pa bo iztisnil ob vznožju oltarja. To je daritev za greh.',
        10: 'Drugo pa bo daroval za žgalno daritev, glede na določen način in duhovnik bo zanj opravil spravo za njegov greh, ki ga je zagrešil in ta mu bo odpuščen.',
        11: 'Toda če ne bo zmožen prinesti dveh grlic ali dveh mladih golobov, potem naj tisti, ki je grešil, za svoj dar prinese deseti del škafa iz fine moke za daritev za greh; nanjo ne bo dal olja niti ne bo nanjo dal kakršnega koli kadila, kajti to je daritev za greh.',
        12: 'Potem bo to prinesel do duhovnika in duhovnik bo vzel prgišče tega, torej spomin od tega in to sežgal na oltarju, glede na daritve, narejene z ognjem Gospodu. To je daritev za greh.',
        13: 'Duhovnik bo zanj opravil spravo glede njegovega greha, ki ga je zagrešil v eni od teh [stvari] in ta mu bo odpuščen. Preostanek pa bo duhovnikov, kot jedilna daritev.‹«',
        14: 'Gospod je spregovoril Mojzesu, rekoč:',
        15: '»Če duša zagreši prekršek in greši zaradi nevednosti v Gospodovih svetih stvareh, potem bo za svoj prekršek iz tropa privedla ovna brez pomanjkljivosti Gospodu, s tvojo oceno po srebrnih šeklih, po svetiščnem šeklu, v daritev za prestopek.',
        16: 'Odkupil se bo zaradi škode, ki jo je storil v sveti stvari in k temu bo dodal peti del in ga dal duhovniku. Duhovnik bo zanj opravil spravo z ovnom daritve za prekršek in to mu bo odpuščeno.',
        17: 'Če duša greši in zagreši katerokoli od teh stvari, ki so po Gospodovih zapovedih prepovedane, da se storijo; čeprav tega ni vedel, je vendarle kriv in bo nosil svojo krivičnost.',
        18: 'Iz tropa bo duhovniku privedel ovna brez pomanjkljivosti, s tvojo oceno, v daritev za prestopek in duhovnik bo zanj opravil spravo glede njegove nevednosti, v kateri je nevedno grešil in tega ni vedel in ta mu bo odpuščena.',
        19: 'To je daritev za prestopek. Zagotovo se je prekršil zoper Gospoda.«',
    },
    6: {
        1: 'Gospod je spregovoril Mojzesu, rekoč:',
        2: '»Če duša greši in zagreši prekršek zoper Gospoda in laže svojemu bližnjemu v tem, kar mu je bilo izročeno, da varuje, ali v družbi, ali v stvari, odvzeti z nasiljem, ali je zavedel svojega bližnjega,',
        3: 'ali je našel to, kar je bilo izgubljeno in glede tega laže in krivo prisega; v čemerkoli izmed vsega tega kar človek dela, v tem greši;',
        4: 'Potem se bo zgodilo, ker je grešil in je kriv, da bo povrnil to, kar je nasilno odvzel proč ali stvar, ki jo je varljivo pridobil ali to, kar mu je bilo izročeno, da varuje ali izgubljeno stvar, ki jo je našel,',
        5: 'ali vse to o čemer je krivo prisegel. To bo torej povrnil v glavnici in k temu bo dodal še petino in to dal tistemu, ki mu pripada, na dan svoje daritve za prekršek.',
        6: 'H Gospodu bo [prek] duhovnika privedel svojo daritev za prestopek, ovna brez pomanjkljivosti iz tropa, s tvojo oceno, v daritev za prestopek.',
        7: 'Duhovnik bo zanj pred Gospodom opravil spravo in odpuščeno mu bo za karkoli od vsega, kar je storil v teh prekrških.«',
        8: 'Gospod je spregovoril Mojzesu, rekoč:',
        9: '»Zapovej Aronu in njegovim sinovom, rekoč: ›To je postava žgalne daritve: ›To je žgalna daritev, ker vso noč, do jutra, gori na oltarju in oltarni ogenj bo gorel v njej.‹',
        10: 'Duhovnik si bo nadel laneno obleko in kratke platnene hlače bo nadel na svoje meso in pobral pepel, ki ga je ogenj na oltarju použil z žgalno daritvijo in ga položil poleg oltarja.',
        11: 'Odložil bo svoje obleke in si nadel druge obleke in pepel odnesel zunaj tabora, na čist prostor.',
        12: 'Ogenj na oltarju naj gori na njem; naj ne bo ugasnjen. Duhovnik naj na njem vsako jutro zažiga les in nanj po vrsti polaga žgalno daritev in na njem naj zažiga tolščo mirovnih daritev.',
        13: 'Ogenj bo vedno gorel na oltarju; nikoli naj ne ugasne.',
        14: 'To je postava jedilne daritve. Aronovi sinovi jo bodo darovali pred Gospodom, pred oltarjem.',
        15: 'Od tega bo vzel prgišče moke jedilne daritve in od olja in vse kadilo, ki je na jedilni daritvi in to bo na oltarju sežgal Gospodu v prijeten vonj, torej spomin na to.',
        16: 'Preostanek pa bodo Aron in njegovi sinovi pojedli. Z nekvašenim kruhom bo pojedena na svetem prostoru. Na dvoru šotorskega svetišča skupnosti jo bodo pojedli.',
        17: 'Ta ne bo pečena s kvasom. To sem jim dal za njihov delež mojih daritev, narejenih z ognjem; to je najsvetejše, kakor je daritev za greh in kakor daritev [za] prekršek.',
        18: 'Vsi moški izmed Aronovih otrok bodo jedli od nje. To bo zakon na veke v vaših rodovih glede Gospodovih daritev, narejenih z ognjem; vsak, kdor se jih dotakne, bo svet.‹«',
        19: 'Gospod je spregovoril Mojzesu, rekoč:',
        20: '»To je dar Arona in njegovih sinov, ki ga bodo darovali Gospodu na dan, ko je maziljen: deseti del škafa fine moke za neprestano jedilno daritev, polovico od tega zjutraj in polovico od tega zvečer.',
        21: 'V ponvi naj bo pripravljena z oljem in ko je ocvrta, jo boš v njej prinesel in pečene koščke jedilne daritve boš daroval v prijeten vonj Gospodu.',
        22: 'To naj daruje duhovnik izmed njegovih sinov, ki je maziljen namesto njega. To je zakon na veke Gospodu; ta naj bo v celoti sežgana.',
        23: 'Kajti vsaka jedilna daritev za duhovnika naj bo v celoti sežgana. Le-ta naj ne bo pojedena.«',
        24: 'Gospod je spregovoril Mojzesu, rekoč:',
        25: '»Govori Aronu in njegovim sinovom, rekoč: ›To je postava daritve za greh pred Gospodom. Na kraju, kjer je zaklana žgalna daritev, bo zaklana daritev za greh. To je najsvetejše.',
        26: 'Jedel jo bo duhovnik, ki jo daruje za greh. Pojedena bo na svetem kraju, na dvoru šotorskega svetišča skupnosti.',
        27: 'Karkoli od tega se bo dotaknilo mesa, naj bo sveto, in ko je kri od te daritve poškropljena na kakršnokoli obleko, boš na svetem prostoru opral to, po čemer je bila poškropljena.',
        28: 'Toda lončena posoda, v kateri je skuhana, naj bo razbita, in če je skuhana v bronastem loncu, naj bo tako odrgnjena kakor pomita v vodi.',
        29: 'Vsi moški izmed duhovnikov bodo jedli od tega. To je najsvetejše.',
        30: 'Nobena daritev za greh, od katere je kakršnakoli kri prinesena v šotorsko svetišče skupnosti, da se z njo pobota na svetem kraju, naj ne bo pojedena. Ta naj bo sežgana v ognju.',
    },
    7: {
        1: 'Prav takšna je postava daritve za prestopek. To je najsvetejše.',
        2: 'Na mestu, kjer koljejo žgalno daritev, bodo zaklali daritev za prestopek in njeno kri bodo poškropili naokoli nad oltarjem.',
        3: 'Od tega bo daroval vso njeno tolščo; tolsti rep in tolščo, ki pokriva drobovje,',
        4: 'dve ledvici in tolščo, ki je na njiju, ki je ob bokih in opno, ki je nad jetri, z dvema ledvicama, to bo vzel proč.',
        5: 'Duhovnik jih bo sežgal na oltarju za daritev, ognjeno daritev Gospodu. To je daritev za prestopek.',
        6: 'Vsak moški med duhovniki naj od tega jé. To naj bo pojedeno na svetem prostoru. To je najsvetejše.',
        7: 'Kakor je daritev za greh, tako je daritev za prestopek. Zanju je ena postava. Duhovnik, ki s tem opravlja spravo, bo to imel.',
        8: 'Duhovnik, ki daruje žgalno daritev kateregakoli človeka, torej duhovnik, bo zase imel kožo žgalne daritve, ki jo je daroval.',
        9: 'Vsa jedilna daritev, ki je spečena v peči in vse, kar je pripravljeno v ponvi za cvrtje in v ponvi, naj bo od duhovnika, ki jo daruje.',
        10: 'Vsako jedilno daritev, pomešano z oljem in suho, naj imajo vsi Aronovi sinovi, eden toliko kakor drugi.',
        11: 'To je postava žrtvovanja mirovnih daritev, ki jih bo daroval Gospodu.',
        12: 'Če jo daruje za zahvaljevanje, potem naj jo daruje z žrtvijo zahvaljevanja nekvašenih kolačev, umešanih z oljem in nekvašenih vafljev, pomazanih z oljem in ocvrtih kolačev, umešanih z oljem iz fine moke.',
        13: 'Poleg kolačev bo za svoj dar daroval kvašen kruh z zahvalno žrtvijo njegovih mirovnih daritev.',
        14: 'Od tega naj daruje enega od celotnega daru za vzdigovalno daritev Gospodu in to naj bo od tistega duhovnika, ki škropi kri mirovnih daritev.',
        15: 'Meso žrtvovanja njegovih mirovnih daritev za zahvaljevanje naj bo pojedeno istega dne, kot je bilo darovano; nič od tega naj ne pusti do jutra.',
        16: 'Toda če je žrtvovanje njegove daritve prisega ali prostovoljno darovanje, naj bo to pojedeno istega dne, kot daruje svojo klavno daritev in tudi naslednji dan naj bo njen ostanek pojeden,',
        17: 'toda preostanek mesa klavne daritve naj bo na tretji dan sežgan z ognjem.',
        18: 'Če bo karkoli od mesa žrtvovanja njegovih mirovnih daritev pojedeno tretji dan, ne bo sprejeto niti ne bo pripisano tistemu, ki je to daroval. To bo ogabnost in duša, ki od tega jé, bo nosila svojo krivičnost.',
        19: 'Meso, ki se dotakne katerekoli nečiste stvari naj ne bo pojedeno; sežgano naj bo z ognjem. Kar se tiče mesa, vsi, ki so čisti, naj od tega jedo.',
        20: 'Toda duša, ki jé od mesa žrtvovanja mirovnih daritev, ki pripadajo Gospodu, ima na sebi svojo nečistost, celo ta duša naj bo iztrebljena iz svojega ljudstva.',
        21: 'Še več, duša, ki se bo dotaknila katerekoli nečiste stvari, kakor je nečistost človeka ali kakršnekoli nečiste živali ali kakšne gnusne nečiste stvari in jé od mesa žrtvovanja mirovnih daritev, ki pripadajo Gospodu, celo ta duša naj bo iztrebljena iz svojega ljudstva.‹«',
        22: 'Gospod je spregovoril Mojzesu, rekoč:',
        23: '»Govori Izraelovim otrokom, rekoč: ›Vi ne boste jedli nobene vrste tolšče od vola, ovce ali koze.',
        24: 'Tolšča živali, ki je sama od sebe poginila in tolšča od tega, kar so živali raztrgale, je lahko uporabljena na katerikoli drug način, toda vi od tega nikakor ne boste jedli.',
        25: 'Kajti kdorkoli jé tolščo živali, od katerih ljudje darujejo ognjeno daritev Gospodu, celo duša, ki to jé, naj bo iztrebljena izmed svojega ljudstva.',
        26: 'Še več, vi ne boste jedli nobene vrste krvi, bodisi od perjadi ali od živine, v kateremkoli izmed svojih prebivališč.',
        27: 'Katerakoli duša, ki jé katerokoli vrsto krvi, celo ta duša naj bo iztrebljena iz svojega ljudstva.‹«',
        28: 'Gospod je spregovoril Mojzesu, rekoč:',
        29: '»Govori Izraelovim otrokom, rekoč: ›Kdor daruje žrtvovanje svojih mirovnih daritev Gospodu, bo prinesel svoj dar Gospodu od žrtvovanja svojih mirovnih daritev.',
        30: 'Njegove lastne roke bodo prinesle Gospodove ognjene daritve, tolščo s prsmi. To bo prinesel, da bodo prsi lahko majane za majalno daritev pred Gospodom.',
        31: 'Duhovnik naj tolščo sežge na oltarju, toda prsi naj bodo od Arona in njegovih sinov.',
        32: 'Desno pleče boste dali duhovniku za vzdigovalno daritev, žrtvovanje svojih mirovnih daritev.',
        33: 'Tisti izmed Aronovih sinov, ki darujejo kri mirovnih daritev in tolščo, bodo imeli za svoj delež desno pleče.',
        34: 'Kajti prsi majanja in pleče vzdigovanja sem vzel Izraelovim otrokom izmed žrtvovanja njihovih mirovnih daritev in jih za vedno z zakonom dal duhovniku Aronu in njegovim sinovom izmed Izraelovih otrok.‹«',
        35: 'To je delež Aronovega maziljenja in maziljenja njegovih sinov izmed ognjenih Gospodovih daritev, na dan, ko jih je prinesel, da bi služil Gospodu v duhovniški službi;',
        36: 'ki ga je Gospod zapovedal, da bi jim bil dan od Izraelovih otrok, na dan, ko jih je mazilil, z zakonom na veke skozi njihove rodove.',
        37: 'To je postava žgalne daritve, jedilne daritve, daritve za greh, daritve za prestopek, uméstitvenih [daritev] in žrtvovanje mirovnih daritev,',
        38: 'ki jih je Gospod zapovedal Mojzesu na gori Sinaj, na dan, ko je Izraelovim otrokom zapovedal, naj svoje darove darujejo Gospodu v Sinajski divjini.',
    },
    8: {
        1: 'Gospod je spregovoril Mojzesu, rekoč:',
        2: '»Vzemi Arona in z njim njegove sinove, obleke, mazilno olje, bikca za daritev za greh, dva ovna in košaro nekvašenega kruha,',
        3: 'in zberi skupaj ves zbor k vratom šotorskega svetišča skupnosti.«',
        4: 'Mojzes je storil, kakor mu je Gospod zapovedal in zbor je bil zbran skupaj k vratom šotorskega svetišča skupnosti.',
        5: 'Mojzes je rekel skupnosti: »To je stvar, ki jo je Gospod zapovedal, da se stori.«',
        6: 'Mojzes je privedel Arona in njegove sinove ter jih umil z vodo.',
        7: 'Nadel mu je plašč, ga opasal s pasom, ga ogrnil s svečanim oblačilom, nanj položil efód in ga opasal s skrbno narejenim pasom efóda in ga s tem prevezal.',
        8: 'Nanj je dal naprsnik. V naprsnik je položil tudi Urím in Tumím.',
        9: 'Turban je položil na njegovo glavo; tudi na turban, torej na njegov sprednji del, je položil zlato ploščico, sveto krono; kakor je Gospod zapovedal Mojzesu.',
        10: 'Mojzes je vzel mazilno olje in mazilil šotorsko svetišče in vse, kar je bilo v njem in to posvetil.',
        11: 'Od tega je sedemkrat poškropil po oltarju in mazilil oltar ter vse njegove posode, tako [okrogel] umivalnik kot njegovo vznožje, da jih posvéti.',
        12: 'Na Aronovo glavo je izlil mazilno olje in ga mazilil, da ga posvéti.',
        13: 'Mojzes je privedel Aronove sinove, nanje položil plašče, jih opasal s pasovi in nanje položil klobučke; kakor je Gospod zapovedal Mojzesu.',
        14: 'Privedel je bikca za daritev za greh. Aron in njegovi sinovi so svoje roke položili na glavo bikca daritve za greh.',
        15: 'Zaklal ga je in Mojzes je vzel kri in jo s svojim prstom dal vsenaokrog na rogove oltarja in očistil oltar in kri izlil ob vznožju oltarja in ga posvetil, da bi na njem opravil pobotanje.',
        16: 'Vzel je vso tolščo, ki je bila na drobovju, opno nad jetri, dve ledvici, njuno tolščo in Mojzes je to sežgal na oltarju.',
        17: 'Toda bikca, njegovo kožo, njegovo meso in njegov iztrebek je z ognjem sežgal zunaj tabora; kakor je Gospod zapovedal Mojzesu.',
        18: 'In privedel je ovna za žgalno daritev, Aron in njegovi sinovi pa so svoje roke položili ovnu na glavo.',
        19: 'Zaklal ga je in Mojzes je kri poškropil naokoli po oltarju.',
        20: 'Ovna je razrezal na koščke in Mojzes je sežgal glavo, koščke in tolščo.',
        21: 'Drobovje in noge je opral v vodi in Mojzes je celotnega ovna sežgal na oltarju. To je bila žgalna daritev v prijeten vonj in ognjena daritev Gospodu; kakor je Gospod zapovedal Mojzesu.',
        22: 'Privedel je drugega ovna, ovna uméstitve, Aron in njegovi sinovi pa so svoje roke položili ovnu na glavo.',
        23: 'In on ga je zaklal. Mojzes je vzel od njegove krvi, jo pomazal na konico Aronovega desnega ušesa, na palec njegove desne roke in na palec njegovega desnega stopala.',
        24: 'Privedel je Aronove sinove in Mojzes je dal od krvi na konico njihovih desnih ušes in na palce njihovih desnih rok in na palce njihovih desnih stopal; in Mojzes je kri poškropil naokoli po oltarju.',
        25: 'Vzel je tolščo, tolsti rep, vso tolščo, ki je bila na drobovju, opno nad jetri, dve ledvici in njuno tolščo ter desno pleče.',
        26: 'Iz košare nekvašenega kruha, ki je bila pred Gospodom, je vzel en nekvašen kolač, kolač oljnatega kruha in en vafelj ter jih položil na tolščo in na desno pleče.',
        27: 'Vse to je dal na Aronove roke in na roke Aronovih sinov in jih majal za majalno daritev pred Gospodom.',
        28: 'Mojzes jih je vzel iz njihovih rok in jih sežgal na oltarju nad žgalno daritvijo. To so bile uméstitvene [daritve] za prijeten vonj. To je ognjena daritev Gospodu.',
        29: 'Mojzes je vzel prsi in jih majal za majalno daritev pred Gospodom, kajti od ovna uméstitve je bil to Mojzesov delež; kakor je Gospod zapovedal Mojzesu.',
        30: 'Mojzes je vzel od mazilnega olja in od krvi, ki je bila na oltarju in to poškropil na Arona, na njegove obleke, na njegove sinove in na obleke njegovih sinov z njim; in posvetil je Arona, njegove obleke, njegove sinove in obleke njegovih sinov z njim.',
        31: 'Mojzes je rekel Aronu in njegovim sinovim: »Meso skuhajte pri vratih šotorskega svetišča skupnosti. Tam ga pojejte s kruhom, ki je v košari uméstitvenih [daritev], kakor sem zapovedal, govoreč: ›Aron in njegovi sinovi bodo to jedli.‹',
        32: 'To, kar pa ostane od mesa in od kruha, boste sežgali z ognjem.',
        33: 'Sedem dni ne boste šli od vrat šotorskega svetišča skupnosti, dokler dnevi vaše uméstitve ne bodo končani, kajti sedem dni vas bo uméščal.',
        34: 'Kakor je storil ta dan, tako je Gospod zapovedal storiti, da za vas opravi spravo.',
        35: 'Zato boste sedem dni, dan in noč, ostajali pri vratih šotorskega svetišča skupnosti in se boste držali Gospodovega naročila, da ne umrete, kajti tako mi je bilo zapovedano.«',
        36: 'Tako so Aron in njegovi sinovi storili vse stvari, ki jih je Gospod zapovedal po Mojzesovi roki.',
    },
    9: {
        1: 'Na osmi dan se je pripetilo, da je Mojzes poklical Arona, njegove sinove in Izraelove starešine.',
        2: 'Aronu je rekel: »Vzemi si mlado tele za daritev za greh in ovna za žgalno daritev, brez pomanjkljivosti in ju daruj pred Gospodom.',
        3: 'Izraelovim otrokom boš govoril, rekoč: ›Vzemite kozlička od koz za daritev za greh ter tele in jagnje, oba enoletna, brez pomanjkljivosti, za žgalno daritev.',
        4: 'Tudi bikca in ovna za mirovno daritev, da žrtvujete pred Gospodom in jedilno daritev umešano z oljem, kajti danes se vam bo prikazal Gospod.‹«',
        5: 'Pred šotorsko svetišče skupnosti so privedli to, kar je Mojzes zapovedal, in vsa skupnost se je približala ter stala pred Gospodom.',
        6: 'Mojzes je rekel: »To je stvar, ki jo je Gospod zapovedal, da naj bi jo storili; in prikazala se vam bo Gospodova slava.«',
        7: 'Mojzes je rekel Aronu: »Pojdi k oltarju in daruj svojo daritev za greh in svojo žgalno daritev in opravi spravo zase in za ljudstvo in daruj dar ljudstva in opravi spravo zanje; kakor je zapovedal Gospod.«',
        8: 'Aron je torej odšel k oltarju in zaklal tele za daritev za greh, ki je bilo zanj.',
        9: 'Aronovi sinovi so k njemu prinesli kri, in svoj prst je pomočil v kri in jo dal na rogove oltarja in kri izlil ob vznožju oltarja.',
        10: 'Toda tolščo, ledvici in opno nad jetri daritve za greh je sežgal na oltarju, kakor je Gospod zapovedal Mojzesu.',
        11: 'Meso in kožo pa je sežgal z ognjem zunaj tabora.',
        12: 'Zaklal je žgalno daritev in Aronovi sinovi so mu podali kri, ki jo je poškropil naokoli nad oltarjem.',
        13: 'Podali so mu žgalno daritev, z njenimi kosi in glavo, in sežgal jih je na oltarju.',
        14: 'Opral je drobovje in noge ter jih sežgal na žgalni daritvi, na oltarju.',
        15: 'Prinesel je dar ljudstva in vzel kozla, ki je bil daritev za greh za ljudstvo in ga zaklal ter ga daroval za greh kakor prvega.',
        16: 'Privedel je žgalno daritev in jo daroval glede na določen način.',
        17: 'Prinesel je jedilno daritev in od nje vzel prgišče in to sežgal na oltarju poleg jutranje žgalne daritve.',
        18: 'Za ljudstvo je zaklal tudi bikca in ovna za žrtvovanje mirovnih daritev, Aronovi sinovi pa so mu podali kri, ki jo je poškropil naokoli po oltarju,',
        19: 'in tolščo bikca in ovna, tolsti rep in to, kar pokriva drobovje, ledvici in opno nad jetri.',
        20: 'Tolščo so položili na prsi in tolščo je sežgal na oltarju.',
        21: 'Prsi in desno pleče je Aron majal za majalno daritev pred Gospodom; kakor je zapovedal Mojzes.',
        22: 'Aron je svojo roko vzdignil proti ljudstvu in jih blagoslovil in prišel dol od darovanja daritve za greh, žgalne daritve in mirovnih daritev.',
        23: 'Mojzes in Aron sta odšla v šotorsko svetišče skupnosti in prišla ven ter blagoslovila ljudstvo in Gospodova slava se je prikazala vsemu ljudstvu.',
        24: 'Tam je prišel ogenj izpred Gospoda in na oltarju použil žgalno daritev in tolščo. Ko je vse ljudstvo to videlo, so zavpili in padli na svoje obraze.',
    },
    10: {
        1: 'Nadáb in Abihú, Aronova sinova, sta vsak izmed njiju vzela svojo kadilnico in vanju dala ogenj in nanju položila kadilo in pred Gospodom darovala tuj ogenj, katerega jim ni zapovedal.',
        2: 'In tam je izšel ogenj od Gospoda in ju použil in umrla sta pred Gospodom.',
        3: 'Potem je Mojzes rekel Aronu: »To je to, kar je Gospod govoril, rekoč: ›Jaz bom posvečen v tistih, ki se mi približajo in pred vsem ljudstvom bom proslavljen.‹« In Aron je ohranil svoj mir.',
        4: 'Mojzes je poklical Mišaéla in Elicafána, sinova Uziéla, ki je bil Aronov stric in jima rekel: »Pridita bliže, odnesita svoja brata izpred svetišča, ven iz tabora.«',
        5: 'Tako sta se približala in ju v njunih plaščih odnesla ven iz tabora; kakor je rekel Mojzes.',
        6: 'Mojzes je rekel Aronu ter Eleazarju in Itamárju, njegovima sinovoma: »Ne odkrijte svojih glav niti ne pretrgajte svojih oblačil, da ne bi umrli in da ne bi nad vse ljudstvo prišel bes, temveč naj vaši bratje, celotna Izraelova hiša objokujejo gorenje, ki ga je vžgal Gospod.',
        7: 'Ne boste šli ven izpred vrat šotorskega svetišča skupnosti, sicer boste umrli, kajti Gospodovo olje maziljenja je na vas.« In storili so glede na Mojzesovo besedo.',
        8: 'Gospod je spregovoril Aronu, rekoč:',
        9: '»Ne pij vina, niti močne pijače, ne ti, niti tvoji sinovi s teboj, ko greste v šotorsko svetišče skupnosti, da ne bi umrli. To naj bo zakon na veke skozi vaše rodove,',
        10: 'da lahko postavite razliko med svetim in nesvetim in med nečistim in čistim,',
        11: 'da lahko Izraelove otroke učite vseh zakonov, ki jim jih je Gospod govoril po Mojzesovi roki.«',
        12: 'Mojzes je spregovoril Aronu ter Eleazarju in Itamárju, njegovima sinovoma, ki sta ostala: »Vzemite jedilno daritev, ki ostaja od Gospodovih daritev, narejenih z ognjem in jejte jo brez kvasa poleg oltarja, kajti to je najsvetejše.',
        13: 'To boste jedli na svetem prostoru, ker je določeno tebi in tvojim sinovom od Gospodovih žrtev, narejenih z ognjem, kajti tako sem zapovedal.',
        14: 'Prsi majanja in pleče vzdigovanja boste jedli na čistem kraju; ti in tvoji sinovi in tvoje hčere s teboj, kajti določene so tebi in tvojim sinovom, ki so bile dane od žrtvovanja mirovnih daritev Izraelovih otrok.',
        15: 'Pleče vzdigovanja in prsi majanja naj prinesejo z daritvami, narejenimi z ognjem tolšče, da majejo to za majalno daritev pred Gospodom. In ta bo tvoja in tvojih sinov s teboj, po zakonu na veke; kakor je zapovedal Gospod.«',
        16: 'Mojzes je marljivo iskal kozla daritve za greh in glej, ta je bil sežgan in bil je jezen na Eleazarja in Itamárja, Aronova sinova, ki sta ostala živa, rekoč:',
        17: '»Zakaj daritve za greh nista jedla na svetem prostoru, glede na to, da je to najsvetejše in Bog vama je dal, da nosita krivičnost skupnosti, da zanje opravita spravo pred Gospodom?',
        18: 'Glejta, njegova kri ni bila privedena znotraj svetega kraja. Zares bi jo morala jesti na svetem kraju, kakor sem ukazal.«',
        19: 'Aron je rekel Mojzesu: »Glej, ta dan so darovali svojo daritev za greh in svojo žgalno daritev pred Gospodom, mene pa so doletele takšne stvari. Če bi danes jedel daritev za greh ali naj bi bila ta sprejeta v Gospodovih očeh?«',
        20: 'Ko je Mojzes to slišal, je bil zadovoljen.',
    },
    11: {
        1: 'Gospod je spregovoril Mojzesu in Aronu, rekoč jima:',
        2: '»Govorita Izraelovim otrokom, rekoč: ›To so živali, ki jih boste jedli med vsemi živalmi, ki so na zemlji.',
        3: 'Karkoli deli kopito in ima preklan parkelj in prežvekuje med živalmi, te boste jedli.',
        4: 'Vendar izmed teh, ki prežvekujejo ali izmed teh, ki delijo kopito, ne boste jedli takšnih kot je kamela, ker prežvekuje, toda ne deli kopita; ta vam je nečista.',
        5: 'Kunca, ker prežvekuje, toda ne deli kopita; ta vam je nečist.',
        6: 'Zajca, ker prežvekuje, toda ne deli kopita; ta vam je nečist.',
        7: 'Svinje, čeprav deli kopito in je s preklanim kopitom, vendar ne prežvekuje; ta vam je nečista.',
        8: 'Od njihovega mesa ne boste jedli in njihovega trupla se ne boste dotikali; te so vam nečiste.',
        9: 'Te boste jedli izmed vseh, ki so v vodah. Karkoli ima plavuti in luske v vodah, v morjih in v rekah, te boste jedli.',
        10: 'Vse, kar nima plavuti in luske v morjih in rekah od vsega, kar se giblje v vodah in od česarkoli živega, kar je v vodah, te naj vam bodo ogabnost.',
        11: 'Te naj vam bodo torej ogabnost. Od njihovega mesa ne boste jedli, temveč boste njihova trupla imeli za ogabnost.',
        12: 'Karkoli v vodah nima plavuti niti lusk, to vam bo ogabnost.',
        13: 'In te so tiste, ki vam bodo ogabnost med perjadjo. Ne smejo se jesti, ogabnost so: orel, brkati ser, ribji orel,',
        14: 'jastreb, kragulj po njegovi vrsti,',
        15: 'vsak krokar po njegovi vrsti,',
        16: '§ sova, nočni sokol, kukavica, sokol po njegovi vrsti,',
        17: 'majhna sova, kormoran, velika sova,',
        18: 'labod, pelikan, egiptovski jastreb,',
        19: 'štorklja, čaplja po svoji vrsti, smrdokavra in netopir.',
        20: 'Vsa perjad, ki leze, hodeč po vseh štirih, vam bo ogabnost.',
        21: 'Vendar od vsake leteče plazeče stvari, ki hodi po vseh štirih, ki ima noge nad svojimi stopali, da z njimi skače po zemlji.',
        22: 'Torej te izmed njih lahko jeste: letečo kobilico po svoji vrsti, plešasto kobilico po svoji vrsti, skakajočo kobilico po svoji vrsti in kobilico po svoji vrsti.',
        23: 'Toda vse druge leteče plazeče stvari, ki imajo štiri nožice, vam bodo ogabnost.',
        24: 'Zaradi teh boste nečisti. Kdorkoli izmed njih se dotakne trupla, bo nečist do večera.',
        25: 'Kdorkoli mora nositi njihovo truplo, bo opral svoja oblačila in bo nečist do večera.',
        26: 'Trupla vsake živali, ki deli kopito in ni s preklanim kopitom niti ne prežvekuje, so vam nečista. Vsak, kdor se jih dotika, bo nečist.',
        27: 'Karkoli gre po svojih tacah med vsemi vrstami živali, ki gredo po vseh štirih, te so vam nečiste. Kdorkoli se dotika njihovega trupla, bo nečist do večera.',
        28: 'Kdorkoli prenaša njihovo truplo, bo opral svoja oblačila in bo nečist do večera. Ta so vam nečista.',
        29: 'Tudi te vam bodo nečiste izmed plazečih stvari, ki se plazijo po zemlji: podlasica, miš, želva po svoji vrsti,',
        30: 'dihur, kameleon, kuščar, polž in krt.',
        31: 'Te so vam nečiste izmed vseh, ki se plazijo; kdorkoli se jih dotakne, ko so mrtve, bo nečist do večera.',
        32: 'Na karkoli katerakoli izmed njih, ko so mrtve, pade, bo to nečisto; bodisi je to kakršnakoli lesena posoda ali obleka ali koža ali vreča ali kakršnakoli posoda je ta, s katero je opravljeno kakršnokoli delo, mora biti postavljena v vodo in ta bo nečista do večera; tako bo očiščena.',
        33: 'Vsaka lončena posoda, v katero katerakoli izmed njih pade, karkoli je [že] v njej, bo to nečisto; in naj se razbije.',
        34: 'Od vse hrane, ki se lahko jé, bo to, na kar pride takšna voda, nečisto. Vsa pijača, ki se lahko pije v vsaki takšni posodi, bo nečista.',
        35: 'Vsaka stvar, na katero pade katerikoli del njihovega trupla, bo nečista, bodisi je to peč ali podstavna kamna za lonce, naj bodo zdrobljeni, kajti ti so nečisti in naj vam bodo nečisti.',
        36: 'Vendar bosta izvir ali vodnjak, v kateri je obilje vode, čista. Toda to, kar se dotakne njihovega trupla, bo nečisto.',
        37: 'Če katerikoli del njihovega trupla pade na katerokoli seme za sejanje, ki bo posejano, bo to čisto.',
        38: 'Toda če bo na seme prišla kakršnakoli voda in nanj pade katerikoli del njihovega trupla, vam bo to nečisto.',
        39: 'Če pogine katerakoli žival, od katere lahko jeste, bo tisti, ki se dotakne njenega trupla, nečist do večera.',
        40: 'Kdor jé od tega trupla, bo opral svoja oblačila in bo nečist do večera. Tudi tisti, ki nosi to truplo, bo opral svoja oblačila in bo nečist do večera.',
        41: 'Vsaka plazeča stvar, ki se plazi po zemlji, bo ogabnost; ta naj se ne jé.',
        42: 'Karkoli gre po trebuhu in karkoli gre po vseh štirih ali karkoli ima več nožic med vsemi plazečimi stvarmi, ki se plazijo po zemlji, teh ne boste jedli, kajti ogabnost so.',
        43: 'Sebe ne boste naredili gnusne s katerokoli plazečo stvarjo, ki se plazi, niti se z njimi ne boste naredili nečiste, da bi bili s tem omadeževani.',
        44: 'Kajti jaz sem Gospod, vaš Bog. Sebe boste torej posvetili in boste sveti, kajti jaz sem svet, niti se ne boste omadeževali z nobeno vrsto plazeče stvari, ki se plazi po zemlji.',
        45: 'Kajti jaz sem Gospod, ki vas izpeljuje gor iz egiptovske dežele, da bi bil vaš Bog. Bodite torej sveti, kajti jaz sem svet.',
        46: 'To je postava živali, perjadi in vsakega živega ustvarjenega bitja, ki se premika v vodah in vsakega živega ustvarjenega bitja, ki se plazi po zemlji,',
        47: 'da naredi razliko med nečistim in čistim in med živaljo, ki se lahko jé in živaljo, ki se ne sme jesti.‹«',
    },
    12: {
        1: 'Gospod je spregovoril Mojzesu, rekoč:',
        2: '»Govori Izraelovim otrokom, rekoč: ›Če je ženska spočela seme in rodila fantka, potem bo nečista sedem dni; nečista bo glede na dneve oddvojitve zaradi njene šibkosti.',
        3: 'Na osmi dan naj bo meso njegove prednje kožice obrezano.',
        4: 'Potem bo nadaljevala v krvi svojega očiščevanja triintrideset dni; ne bo se dotaknila nobene posvečene stvari niti prišla v svetišče, dokler se dnevi njenega očiščevanja ne bodo dopolnili.',
        5: 'Toda če rodi deklico, potem bo nečista dva tedna, kakor v svoji oddvojitvi, in v krvi svojega očiščevanja naj nadaljuje šestinšestdeset dni.',
        6: 'Ko so dnevi njenega očiščenja dopolnjeni za sina ali za hčer, bo prinesla duhovniku, k vratom šotorskega svetišča skupnosti, enoletno jagnje za žgalno daritev in mladega goloba ali grlico za daritev za greh,',
        7: 'ki ga bo daroval pred Gospodom in zanjo opravil spravo; in očiščena bo pred virom svoje krvi. To je postava za tisto, ki je rodila fantka ali punčko.',
        8: 'Če ni zmožna prinesti jagnjeta, potem naj prinese dve grlici ali dva mlada goloba; enega za žgalno daritev in drugega za daritev za greh. Duhovnik bo zanjo opravil spravo in bo čista.‹«',
    },
    13: {
        1: 'Gospod je spregovoril Mojzesu in Aronu, rekoč:',
        2: '»Če bo imel kak človek na koži svojega mesa dvignjeno mesto, krasto ali svetlo pego in bo ta na koži njegovega mesa podobna nadlogi gobavosti, potem naj bo priveden k duhovniku Aronu ali k enemu izmed njegovih sinov, duhovnikov.',
        3: 'Duhovnik bo pogledal na nadlogo na koži mesa. Ko je dlaka na nadlogi postala bela in je nadloga videti globlja kakor koža njegovega mesa, je to nadloga gobavosti. Duhovnik bo pogledal nanj in ga proglasil za nečistega.',
        4: 'Če je svetla pega na koži njegovega mesa bela in na pogled ni globlja kakor koža in se njene dlake niso pobelile, potem naj duhovnik tistega, ki ima nadlogo, zapre za sedem dni.',
        5: 'Duhovnik ga bo sedmi dan pregledal in glej, če nadloga v njegovem pogledu ostane in se nadloga ni razširila po koži, potem ga bo duhovnik zaprl še za nadaljnjih sedem dni.',
        6: 'Duhovnik naj ga sedmi dan ponovno pregleda in glej, če bo nadloga nekako temna in se nadloga na koži ne širi, ga bo duhovnik proglasil za čistega. To je samo krasta. Opral bo svoja oblačila in bo čist.',
        7: 'Toda če se krasta precej razširi po koži, potem ko ga je za njegovo očiščenje videl duhovnik, naj ga duhovnik ponovno pregleda.',
        8: 'In če duhovnik vidi, da se krasta po koži širi, potem ga bo duhovnik proglasil za nečistega. To je gobavost.',
        9: 'Kadar je nadloga gobavosti na človeku, potem bo ta priveden k duhovniku',
        10: 'in duhovnik ga bo pregledal. Glej, če bo dvignjeno mesto na koži belo in če so dlake postale bele in je tam hitro divje meso na dvignjenem mestu,',
        11: 'je to stara gobavost na koži njegovega mesa in duhovnik ga bo proglasil za nečistega in ga ne bo zaprl, kajti on je nečist.',
        12: 'Če gobavost izbruhne naokoli po koži in gobavost prekrije vso kožo tistega, ki ima nadlogo, od njegove glave, celo do njegovega stopala, kjerkoli duhovnik pogleda,',
        13: 'potem bo duhovnik preudaril. Glej, če je gobavost pokrila vse njegovo meso, bo tega, ki ima nadlogo, proglasil za čistega. Vse se je spremenilo v belo. Ta je čist.',
        14: 'Toda ko se na njem pojavi divje meso, bo nečist.',
        15: 'Duhovnik bo pregledal divje meso in ga proglasil, da je nečist, kajti divje meso je nečisto. To je gobavost.',
        16: 'Ali če je divje meso ponovno spremenjeno v belo, bo prišel k duhovniku',
        17: 'in duhovnik ga bo pregledal. Glej, če se je nadloga spremenila v belo, potem bo duhovnik tistega, ki ima nadlogo, proglasil za čistega. On je čist.',
        18: 'Tudi meso, torej v koži na njem, v kateri je bila razjeda in je ozdravljeno',
        19: 'in je na mestu razjede belo vzdignjeno mesto ali svetla pega, bela in malce rdečkasta in je ta pokazana duhovniku',
        20: 'in če bo, ko jo duhovnik pregleda, na videz nižja od kože in bo njena dlaka spremenjena v belo, ga bo duhovnik proglasil za nečistega. To je nadloga gobavosti, ki je izbruhnila iz razjede.',
        21: 'Toda če duhovnik to pogleda in glej, tam ni belih dlak in če ni nižje kakor koža, temveč je nekako temno, potem ga bo duhovnik zaprl za sedem dni',
        22: 'in če se precej razširi po koži, potem ga bo duhovnik proglasil za nečistega. To je nadloga.',
        23: 'Toda če svetla pega ostaja na svojem mestu in se ni razširila, je to vnetna razjeda in duhovnik ga bo proglasil za čistega.',
        24: 'Ali če je na koži kakršnokoli meso, na katerem je opeklina in ima divje meso te opekline belo svetlo pego, malce rdečkasto ali belo,',
        25: 'potem bo duhovnik pogledal na to. Glej, če se je dlaka na svetli pegi pobelila in je na videz globlja od kože, je to gobavost, ki je izbruhnila iz opekline. Zato ga bo duhovnik proglasil za nečistega. To je nadloga gobavosti.',
        26: 'Toda če duhovnik na to pogleda in glej, tam ni nobene bele dlake na svetli pegi in ta ni nižja kakor ostala koža, temveč je nekako temna, potem ga bo duhovnik zaprl za sedem dni.',
        27: 'Duhovnik ga bo sedmi dan pogledal in če je to precej razširjeno po koži, potem ga bo duhovnik proglasil za nečistega. To je nadloga gobavosti.',
        28: 'Če pa svetla pega ostane na svojem mestu in se ne razširi po koži, temveč je ta nekako temna, je to dvignjeno mesto od opekline in duhovnik ga bo proglasil za čistega, kajti to je vnetje od opekline.',
        29: 'Če ima moški ali ženska nadlogo na glavi ali na bradi,',
        30: 'potem bo duhovnik pregledal nadlogo in glej, če je ta na videz globlja od kože in so tam v njej tanke rumene dlake, potem ga bo duhovnik proglasil za nečistega. To je luskavica, celo gobavost na glavi ali bradi.',
        31: 'Če duhovnik pogleda na nadlogo luskavice in glej, če ta na videz ni globlja kakor koža in v njej ni črne dlake, potem bo duhovnik za sedem dni zaprl tistega, ki ima nadlogo luskavice',
        32: 'in na sedmi dan bo duhovnik pogledal nadlogo. Glej, če se luskavica ne razširi in v njej ni rumene dlake in luskavica na videz ni globlja od kože,',
        33: 'naj bo obrit, toda luskavica naj ne bo obrita, in duhovnik naj tistega, ki ima luskavico, zapre še za sedem dni',
        34: 'in na sedmi dan bo duhovnik pogledal na luskavico. Glej, če se luskavica ni razširila po koži niti na videz ni globlja od kože, potem ga bo duhovnik proglasil za čistega in opral si bo svoja oblačila in bo čist.',
        35: 'Toda če se je luskavica po njegovem očiščevanju precej razširila po koži,',
        36: 'potem naj duhovnik pogleda nanj. Glej, če se je luskavica razširila po koži, duhovnik ne bo iskal rumenih dlak; ta je nečist.',
        37: 'Toda če luskavica na pogled miruje in tam niso zrasle črne dlake, potem je luskavica ozdravljena, ta je čist in duhovnik ga bo proglasil za čistega.',
        38: 'Če imata moški ali ženska na koži svojega mesa svetle pege, torej bele svetle pege,',
        39: 'potem bo duhovnik pogledal. Glej, če so svetle pege na koži njunega mesa temno bele, je to pegasta točka, ki raste na koži. Ta je čist.',
        40: 'Moški, katerega lasje so odpadli iz njegove glave, je plešast; vendar je čist.',
        41: 'Kdor ima svoje lase odpadle od dela njegove glave proti njegovemu obrazu, ta je čelno plešast; vendar je čist.',
        42: 'Če je na plešasti glavi ali golem čelu bela rdečkasta pega, je to gobavost, ki je pognala na njegovi plešasti glavi ali na njegovem plešastem čelu.',
        43: 'Potem bo duhovnik pogledal nanj. Glej, če je vzdignjeno mesto na njegovi plešasti glavi ali na njegovem plešastem čelu belo rdečkasto, kakor se pojavlja gobavost na koži mesa,',
        44: 'je ta gobav moški, on je nečist. Duhovnik ga bo proglasil popolnoma nečistega; njegova nadloga je na njegovi glavi.',
        45: 'Gobavec, na katerem je nadloga, naj ima pretrgana oblačila, golo glavo in svojo zgornjo ustnico naj pokriva in naj kliče: ›Nečist, nečist.‹',
        46: 'Vse dni, v katerih bo na njem nadloga, naj bo omadeževan; nečist je. Prebiva naj sam; zunaj tabora naj bo njegovo prebivališče.',
        47: 'Tudi obleka, na kateri je nadloga gobavosti, bodisi je ta volnena ali lanena obleka;',
        48: 'bodisi je ta na osnutku ali na votku; iz lanu ali iz volne; bodisi na usnju ali na katerikoli stvari, narejeni iz usnja,',
        49: 'in če je nadloga na obleki ali na usnju zelenkasta ali rdečkasta, bodisi na osnutku ali na votku, ali na čemurkoli iz usnja, je to nadloga gobavosti in pokazana bo duhovniku.',
        50: 'Duhovnik bo pogledal na nadlogo in za sedem dni zaprl to, kar ima nadlogo.',
        51: 'Sedmi dan naj pogleda na nadlogo. Če se je nadloga razširila po obleki, bodisi po osnutku ali po votku, ali na usnju ali na kateremkoli delu, narejenemu iz usnja, potem je nadloga nadležna gobavost; to je nečisto.',
        52: 'Zato bo sežgal to obleko, bodisi je to osnutek ali votek, na volni ali na lanu ali kakršnakoli usnjena stvar, na kateri je nadloga, kajti to je nadležna gobavost; to bo sežgano v ognju.',
        53: 'Če bo duhovnik pogledal in glej, nadloga ni razširjena na obleki, bodisi na osnutku ali na votku ali na kakršnikoli usnjeni stvari,',
        54: 'potem bo duhovnik zapovedal, da operejo stvar, na kateri je nadloga in jo bo zaprl še za sedem dni.',
        55: 'Duhovnik bo pogledal na nadlogo, potem ko je umita. Glej, če nadloga ni spremenila svoje barve in se nadloga ni razširila, je to nečisto. To boš sežgal v ognju. To je notranja razjeda, bodisi je ta znotraj ali zunaj.',
        56: 'Če duhovnik pogleda in glej, nadloga je po umivanju nekoliko potemnela, potem jo bo iztrgal iz obleke ali iz usnja ali iz osnutka ali iz votka.',
        57: 'Če se še vedno pojavlja na obleki, bodisi na osnutku ali na votku ali na čemerkoli iz usnja, je to razširjajoča se nadloga. To, na čemer je nadloga, boš sežgal z ognjem.',
        58: 'Obleko, bodisi osnutek ali votek ali kakršna koli stvar iz usnja je to, jo boš umil. Če je nadloga odšla od njih, potem bo to drugič umito in bo čisto.',
        59: 'To je postava nadloge gobavosti na obleki iz volne ali lanu, bodisi je na osnutku ali na votku ali na katerikoli stvari iz usnja, da se razglasi za čisto ali da se proglasi za nečisto.«',
    },
    14: {
        1: 'Gospod je spregovoril Mojzesu, rekoč:',
        2: '»To bo postava za gobavca na dan njegovega očiščenja. Pripeljan bo k duhovniku',
        3: 'in duhovnik bo šel naprej iz tabora in duhovnik bo pogledal in glej, če je na gobavcu nadloga gobavosti ozdravljena,',
        4: 'potem bo duhovnik zapovedal, da za tistega, ki naj bi bil očiščen, vzamejo dve ptici, živi in čisti, cedrov les, škrlat in izop,',
        5: 'in duhovnik bo zapovedal, da bo ena izmed ptic zaklana v lončeni posodi nad tekočo vodo.',
        6: 'Glede žive ptice, jo bo vzel s cedrovim lesom, škrlatom in izopom in jih bo skupaj z živo ptico pomočil v kri ptice, ki je bila zaklana nad tekočo vodo.',
        7: 'To bo sedemkrat poškropil na tistega, ki naj bi bil očiščen gobavosti in proglasil ga bo za čistega in živo ptico bo izpustil prosto na odprto polje.',
        8: 'Ta, ki naj bo očiščen, bo opral svoja oblačila in obril vse dlake in se umil v vodi, da bo lahko čist. Potem bo prišel v tabor in sedem dni ostajal zunaj svojega šotora.',
        9: 'Toda na sedmi dan, ko bo obril vse dlake s svoje glave, svoje brade in svojih obrvi, bo obril celo vso svojo dlako in v vodi bo opral svoja oblačila in tudi svoje meso bo umil in bo čist.',
        10: 'Na osmi dan bo vzel dva jagenjčka, samca brez pomanjkljivosti in eno jagnjico prvega leta, brez pomanjkljivosti in tri desetinke fine moke za jedilno daritev, pomešano z oljem in en vrček olja.',
        11: 'Duhovnik, ki ga očiščuje, bo pred Gospodom, pri vratih šotorskega svetišča skupnosti, predstavil človeka, ki naj bi bil očiščen in te stvari.',
        12: 'Duhovnik bo vzel enega jagenjčka, samca in ga daroval za daritev za greh in vrček olja ter ju majal pred Gospodom za majalno daritev.',
        13: 'Jagnje bo zaklal na kraju, kjer bo zaklal daritev za greh in žgalno daritev, na svetem kraju, kajti daritev za greh je duhovnikova, kot tudi daritev za prestopek. To je najsvetejše.',
        14: 'Duhovnik bo vzel nekaj krvi daritve za prestopek in duhovnik jo bo dal na konico desnega ušesa tistega, ki naj bo očiščen in na palec njegove desne roke in na palec njegovega desnega stopala.',
        15: 'Duhovnik bo vzel nekaj od vrčka olja in to izlil na dlan svoje leve roke',
        16: 'in duhovnik bo svoj desni prst pomočil v olje, ki je v njegovi levi roki in olje bo s svojim prstom sedemkrat poškropil pred Gospodom.',
        17: 'Preostanek olja, ki je v njegovi roki, bo duhovnik dal na konico desnega ušesa tistega, ki naj bo očiščen in na palec njegove desne roke in na palec njegovega desnega stopala, na kri daritve za prestopek.',
        18: 'Ostanek olja, ki je v duhovnikovi roki pa naj izlije na glavo tistega, ki naj bo očiščen in duhovnik bo zanj opravil spravo pred Gospodom.',
        19: 'Duhovnik bo daroval daritev za greh in opravil spravo za tistega, ki naj bo očiščen svoje nečistosti in potem bo zaklal žgalno daritev.',
        20: 'Duhovnik bo na oltarju daroval žgalno daritev in jedilno daritev, in duhovnik bo zanj opravil spravo in on bo čist.',
        21: 'Če pa je reven in ne more dobiti toliko, potem bo vzel eno jagnje za daritev za prestopek, da bo majano, da opravi spravo zanj in eno desetinko fine moke, umešane z oljem za jedilno daritev in vrček olja',
        22: 'ter dve grlici ali dva mlada goloba, takšne, kot jih lahko dobi; ena bo za daritev za greh, druga pa za žgalno daritev.',
        23: 'Na osmi dan jih bo prinesel duhovniku za svoje očiščenje, k vratom šotorskega svetišča skupnosti pred Gospoda.',
        24: 'Duhovnik bo vzel jagnje daritve za prestopek in vrček olja in duhovnik ju bo majal za majalno daritev pred Gospodom.',
        25: 'Zaklal bo jagnje daritve za prekršek in duhovnik bo vzel nekaj od krvi daritve za prekršek in jo dal na konico desnega ušesa tistega, ki naj bo očiščen in na palec njegove desne roke in na palec njegovega desnega stopala',
        26: 'in duhovnik bo nekaj olja izlil v dlan svoje leve roke,',
        27: 'in duhovnik bo s svojim desnim prstom nekaj olja, ki je v njegovi levi roki, sedemkrat poškropil pred Gospodom.',
        28: 'Duhovnik bo dal od olja, ki je v njegovi roki, na konico desnega ušesa tistega, ki naj bo očiščen in na palec njegove desne roke in na palec njegovega desnega stopala, na mestu krvi daritve za prestopek.',
        29: 'Preostanek olja, ki je v duhovnikovi roki, pa bo dal na glavo tistega, ki naj bo očiščen, da zanj opravi spravo pred Gospodom.',
        30: 'Daroval bo eno izmed grlic ali izmed mladih golobov, takega, kot ga lahko dobi,',
        31: 'torej takšnega, kot ga je zmožen dobiti, enega za daritev za greh in drugega za žgalno daritev, z jedilno daritvijo, in duhovnik bo za tistega, ki naj bo očiščen pred Gospodom, opravil spravo.',
        32: 'To je postava tistega, na katerem je nadloga gobavosti, čigar roka ni zmožna dobiti tega, kar pripada njegovemu očiščenju.«',
        33: 'Gospod je spregovoril Mojzesu in Aronu, rekoč:',
        34: '»Ko boste prišli v kánaansko deželo, ki sem vam jo dal za posest in položim nadlogo gobavosti v hišo dežele vaše posesti,',
        35: 'in kdor je lastnik hiše in pride in pove duhovniku, rekoč: ›Zdi se mi, da je tam v hiši, kakor bi bila nadloga,',
        36: 'potem bo duhovnik zapovedal, da izpraznijo hišo, preden duhovnik vstopi vanjo, da bi videl nadlogo, da ne bi vse, kar je v hiši, postalo nečisto in potem bo duhovnik vstopil, da pogleda hišo.',
        37: 'Pogledal bo nadlogo in glej, če je nadloga na zidovih hiše, z ugreznjenimi mesti, zelenkastimi ali rdečimi, ki so na pogled nižja kakor zid,',
        38: 'potem bo duhovnik šel ven iz hiše, k hišnim vratom in bo za sedem dni zaprl hišo.',
        39: 'Duhovnik bo sedmi dan ponovno prišel in pogledal. Glej, če je nadloga razširjena po zidovih hiše,',
        40: 'potem bo duhovnik zapovedal, da odnesejo kamne, na katerih je nadloga in jih odvržejo na nečist kraj zunaj mesta,',
        41: 'hišo pa bo dal znotraj vso ostrgati in ostrgan prah bodo izsuli zunaj mesta na nečist kraj.',
        42: 'Vzeli bodo druge kamne in jih položili na mesto tistih kamnov in vzel bo drugo malto in ometal hišo.',
        43: 'Če nadloga ponovno pride in izbruhne v hiši, potem ko je kamne odvzel proč in potem, ko je ostrgal hišo in potem ko je ta ometana,',
        44: 'potem bo prišel duhovnik in pogledal in glej, če se je nadloga razširila po hiši, je to nadležna gobavost v hiši. Ta je nečista.',
        45: 'Porušil bo hišo, njene kamne, njen les in vso malto hiše in jih odnesel naprej, ven iz mesta, na nečist kraj.',
        46: 'Poleg tega bo kdor gre v hišo, medtem ko je ta zaprta, nečist do večera.',
        47: 'Kdor leži v hiši, bo opral svoja oblačila in kdor jé v hiši, bo opral svoja oblačila.',
        48: 'Če bo duhovnik vstopil in pogledal na to in glej, nadloga se ni razširila po hiši, potem ko je bila hiša ometana; potem bo duhovnik hišo proglasil za čisto, ker je nadloga ozdravljena.',
        49: 'Da hišo očisti, bo vzel dve ptici, cedrov les, škrlat in izop.',
        50: 'Eno izmed ptic bo zaklal v lončeni posodi nad tekočo vodo',
        51: 'in vzel bo cedrov les, izop, škrlat in živo ptico ter jih pomočil v krvi zaklane ptice in v tekočo vodo in hišo sedemkrat poškropil.',
        52: 'Hišo bo očistil s krvjo ptice, s tekočo vodo, z živo ptico, s cedrovim lesom, z izopom in škrlatom,',
        53: 'toda živo ptico bo izpustil ven iz mesta, na odprta polja in opravil spravo za hišo, in ta bo čista.',
        54: 'To je postava za vse vrste nadlog gobavosti in luskavice',
        55: 'ter za gobavost obleke in hiše,',
        56: 'za oteklino, za krasto in za svetlo pego,',
        57: 'da uči, kdaj je to nečisto in kdaj je to čisto. To je postava gobavosti.‹«',
    },
    15: {
        1: 'Gospod je spregovoril Mojzesu in Aronu, rekoč:',
        2: '»Govorita Izraelovim otrokom in jim recita: ›Kadar ima katerikoli moški tekoč izliv iz svojega mesa, je zaradi svojega izliva nečist.',
        3: 'To bo njegova nečistost v njegovem izlivu; bodisi iz njegovega mesa teče z njegovim izlivom, ali se v njegovem mesu ustavlja izliv, je to nečistost.',
        4: 'Vsaka postelja, na kateri leži ta, ki ima izliv, je nečista, in vsaka stvar, na kateri on sedi, bo nečista.',
        5: 'Kdorkoli se dotakne njegove postelje, naj opere svoja oblačila in se okopa v vodi in bo nečist do večera.',
        6: 'Kdor sedi na katerikoli stvari, na kateri je sedel tisti, ki ima izliv, bo opral svoja oblačila in se okopal v vodi in bo nečist do večera.',
        7: 'Kdor se dotika mesa tistega, ki ima izliv, bo opral svoja oblačila in se okopal v vodi in bo nečist do večera.',
        8: 'Če tisti, ki ima izliv, pljune na tistega, ki je čist, potem bo ta opral svoja oblačila in se okopal v vodi in bo nečist do večera.',
        9: 'Kdor osedla karkoli, na čemer jaha tisti, ki ima izliv, bo nečist.',
        10: 'Kdorkoli se dotakne česarkoli, kar je bilo pod njim, bo nečist do večera, in kdor nosi katerokoli izmed teh stvari, naj opere svoja oblačila in se okopa v vodi in bo nečist do večera.',
        11: 'Kogarkoli se dotakne tisti, ki ima izliv in si rok ni umil v vodi, bo opral svoja oblačila in se okopal v vodi in bo nečist do večera.',
        12: 'Lončena posoda, ki se je dotakne tisti, ki ima izliv, bo razbita; vsaka lesena posoda pa bo umita v vodi.',
        13: 'In ko se je ta, ki ima izliv, očistil svojega izliva, potem si bo štel sedem dni za svoje očiščevanje, opral svoja oblačila, svoje meso okopal v tekoči vodi in bo čist.',
        14: 'Osmi dan si bo vzel dve grlici ali dva mlada goloba in bo prišel pred Gospoda, k vratom šotorskega svetišča skupnosti in ju bo dal duhovniku.',
        15: 'Duhovnik ju bo daroval, enega za daritev za greh in drugega za žgalno daritev. Duhovnik bo pred Gospodom zaradi njegovega izliva zanj opravil spravo.',
        16: 'Če iz kateregakoli moškega steče seme združenja, potem bo vse svoje meso umil v vodi in bo nečist do večera.',
        17: 'Vsaka obleka in vsako usnje, na katerem je seme združenja, bo oprano v vodi in bo nečisto do večera.',
        18: 'Tudi ženska, s katero moški leži s semenom združenja, se bosta oba okopala v vodi in bosta nečista do večera.',
        19: 'Če ima ženska izliv in je njen izliv v njenem mesu kri, bo ločena posebej za sedem dni. Kdorkoli se je dotakne, bo nečist do večera.',
        20: 'Vsaka stvar, na kateri ona v svoji oddvojitvi leži, bo nečista. Tudi vsaka stvar, na kateri ona sedi, bo nečista.',
        21: 'Kdorkoli se dotakne njene postelje, bo opral svoja oblačila in se okopal v vodi in bo nečist do večera.',
        22: 'Kdorkoli se dotakne katerekoli stvari, na kateri je sedela, bo opral svoja oblačila in se okopal v vodi in bo nečist do večera.',
        23: 'In če je to na njeni postelji ali na katerikoli stvari ona sedi, ko se je ta dotakne, bo nečist do večera.',
        24: 'Če katerikoli moški sploh leži z njo in je njena nečistost nad njim, bo nečist sedem dni in vsa postelja, na kateri on leži, bo nečista.',
        25: 'Če ima ženska vir njene krvi mnogo dni dlje od časa njene oddvojitve ali če ta teče preko časa njene oddvojitve; vseh dni izliva njene nečistosti bo kakor na dneve njene oddvojitve; ona bo nečista.',
        26: 'Vsaka postelja, na kateri leži vse dni svojega izliva, ji bo kakor postelja oddvojitve in na čemerkoli ona sedi, bo nečisto, kakor nečistost njene oddvojitve.',
        27: 'Kdorkoli se dotika teh stvari bo nečist in bo opral svoja oblačila in se okopal v vodi in bo nečist do večera.',
        28: 'Toda če bo očiščena svojega izliva, potem si bo štela sedem dni in potem bo čista.',
        29: 'Na osmi dan si bo vzela dve grlici ali dva mlada goloba in ju prinesla k duhovniku, k vratom šotorskega svetišča skupnosti.',
        30: 'Duhovnik bo enega daroval za daritev za greh, drugega pa za žgalno daritev. Duhovnik bo zaradi izliva njene nečistosti zanjo opravil spravo pred Gospodom.',
        31: 'Tako bodo Izraelove otroke oddvojili od njihove nečistosti, da v svoji nečistosti ne umrejo, ko omadežujejo moje šotorsko svetišče, ki je med njimi.',
        32: 'To je postava za tistega, ki ima izliv in tistega, katerega seme gre od njega in je s tem omadeževan,',
        33: 'in o tisti, ki je bolna od svoje nečistosti in o tistem, ki ima izliv, od moškega ali od ženske in o tistem, ki leži s tisto, ki je nečista.‹«',
    },
    16: {
        1: 'Gospod je spregovoril Mojzesu po smrti Aronovih dveh sinov, ko sta darovala pred Gospodom in umrla,',
        2: 'in Gospod je rekel Mojzesu: »Govori svojemu bratu Aronu, da ne pride ob vseh časih v sveti prostor znotraj zagrinjala, pred sedež milosti, ki je na skrinji, da ne umre, kajti jaz se bom v oblaku prikazal nad sedežem milosti.',
        3: 'Tako bo Aron prišel na sveti kraj: z mladim bikcem za daritev za greh in ovnom za žgalno daritev.',
        4: 'Nadel si bo svet lanen plašč, na svojem mesu bo imel kratke platnene hlače, opasan bo z lanenim pasom in okrašen z lanenim turbanom. To so sveta oblačila, zato bo svoje meso umil v vodi in si jih tako nadel.',
        5: 'Od zbora Izraelovih otrok bo vzel dva kozlička od koz za daritev za greh in enega ovna za žgalno daritev.',
        6: 'Aron bo daroval svojega bikca daritve za greh, ki je zanj ter opravil spravo zase in za svojo hišo.',
        7: 'Vzel bo dva kozla in ju postavil pred Gospoda, pri vratih šotorskega svetišča skupnosti.',
        8: 'Aron bo metal žrebe med dvema kozloma. En žreb za Gospoda, drugi žreb pa za ubežnega kozla.',
        9: 'Aron bo privedel kozla, na katerega je padel Gospodov žreb in ga daroval za daritev za greh.',
        10: 'Toda kozel, na katerega pade žreb, da bo ubežen kozel, bo živ postavljen pred Gospoda, da z njim opravi spravo in da ga za ubežnega kozla spusti v divjino.',
        11: 'Aron bo privedel bikca daritve za greh, ki je zanj in opravil spravo zase in za svojo hišo in zaklal bo bikca daritve za greh, ki je zanj,',
        12: 'in izpred oltarja, pred Gospodom, bo vzel kadilnico, polno gorečega ognjenega oglja in svoji roki polni drobno zdrobljenega dišečega kadila in to bo prinesel znotraj zagrinjala.',
        13: 'Kadilo bo položil na ogenj pred Gospodom, da oblak kadila lahko pokrije sedež milosti, ki je nad pričevanjem, da ne umre.',
        14: 'Vzel bo od krvi bikca in jo s svojim prstom poškropil nad sedežem milosti proti vzhodu. Pred sedežem milosti bo s svojim prstom sedemkrat poškropil kri.',
        15: 'Potem bo zaklal kozla daritve za greh, ki je za ljudstvo in njegovo kri prinesel znotraj zagrinjala in s to krvjo storil, kakor je storil s krvjo bikca in jo poškropil nad sedežem milosti in pred sedežem milosti.',
        16: 'Zaradi nečistosti Izraelovih otrok in zaradi njihovih prestopkov v vseh njihovih grehih bo opravil spravo za svet kraj in tako bo storil za šotorsko svetišče skupnosti, ki ostaja med njimi v sredi njihove nečistosti.',
        17: 'Tam ne bo nobenega moža v šotorskem svetišču skupnosti, ko gre vanj, da opravi spravo na svetem kraju, dokler ne pride ven in je opravil spravo zase, za svojo družino in za vso Izraelovo skupnost.',
        18: 'Odšel bo ven, k oltarju, ki je pred Gospodom in opravil spravo zanj. Vzel bo od krvi bikca in od krvi kozla in to položil naokoli, na oltarne rogove.',
        19: 'S svojim prstom bo nanj sedemkrat poškropil od krvi, ga očistil in ga posvetil pred nečistostjo Izraelovih otrok.',
        20: 'Ko zaključi očiščenje svetega kraja, šotorskega svetišča skupnosti in oltarja, bo privedel živega kozla,',
        21: 'in Aron bo obe svoji roki položil na glavo živega kozla in nad njim priznal vse krivičnosti Izraelovih otrok in vse njihove prestopke v vseh njihovih grehih, s tem, da jih položi na glavo kozla in ga po roki primernega moža pošlje proč, v divjino.',
        22: 'Kozel bo na sebi nosil vse njihove krivičnosti v nenaseljeno deželo in kozla bo spustil v divjino.',
        23: 'Aron bo prišel v šotorsko svetišče skupnosti in odložil lanene obleke, ki jih je oblekel, ko je odšel v sveti kraj in jih bo pustil tam.',
        24: 'Svoje meso bo z vodo umil na svetem kraju in si nadel svoje obleke in prišel naprej ter daroval svojo žgalno daritev, žgalno daritev za ljudstvo in opravil spravo zase in za ljudstvo.',
        25: 'Tolščo daritve za greh bo sežgal na oltarju.',
        26: 'Tisti, ki je spustil kozla za ubežnega kozla, bo opral svoja oblačila in svoje meso umil v vodi in potem pride v tabor.',
        27: 'Bikca daritve za greh in kozla daritve za greh, čigar kri je bila prinesena, da opravi spravo na svetem kraju, bo nekdo odnesel zunaj tabora, v ognju pa bodo sežgali njihove kože, njihovo meso in njihov iztrebek.',
        28: 'Kdor jih zažiga bo opral svoja oblačila in svoje telo umil v vodi in potem bo prišel v tabor.',
        29: 'To bo med vami zakon na veke, da boste v sedmem mesecu, na deseti dan meseca, ponižali svoje duše in sploh ne boste počeli nobenega dela; naj bo to nekdo iz vaše lastne dežele ali tujec, ki začasno prebiva med vami,',
        30: 'kajti na ta dan bo duhovnik opravil spravo za vas, da vas očisti, da boste pred Gospodom lahko čisti pred vsemi svojimi grehi.',
        31: 'To vam bo šabatni počitek in svoje duše boste strli, po zakonu na veke.',
        32: 'Duhovnik, ki ga bo mazilil in ki ga bo uméstil, da služi v duhovniški službi na mestu njegovega očeta, bo opravil spravo in si nadel lanena oblačila, torej sveta oblačila,',
        33: 'in ta bo opravil spravo za sveto svetišče in ta bo opravil spravo za šotorsko svetišče skupnosti in za oltar in ta bo opravil spravo za duhovnike in za vse ljudstvo skupnosti.',
        34: 'To vam bodi večen zakon, da enkrat letno opravite spravo za Izraelove otroke, za vse njihove grehe.« In storil je, kakor je Gospod zapovedal Mojzesu.',
    },
    17: {
        1: 'Gospod je spregovoril Mojzesu, rekoč:',
        2: '»Govori Aronu, njegovim sinovom in vsem Izraelovim otrokom ter jim reci: ›To je stvar, ki jo je Gospod zapovedal, rekoč:',
        3: '›Katerikoli človek bo tam iz Izraelove hiše, ki kolje vola ali jagnje ali kozo v taboru ali da to kolje izven tabora,',
        4: 'pa tega ne prinaša k vratom šotorskega svetišča skupnosti, da daruje dar Gospodu pred Gospodovim šotorskim svetiščem, bo kri pripisana tistemu človeku. Prelil je kri, in ta mož bo iztrebljen izmed svojega ljudstva,',
        5: 'z namenom, da Izraelovi otroci lahko prinesejo svoje klavne daritve, ki jih darujejo na odprtem polju, torej, da jih lahko privedejo h Gospodu, k vratom šotorskega svetišča skupnosti, k duhovniku in jih darujejo za mirovna žrtvovanja Gospodu.',
        6: 'Duhovnik bo kri poškropil na Gospodov oltar pri vratih šotorskega svetišča skupnosti in tolščo sežgal v prijeten vonj Gospodu.',
        7: '§ Svojih klavnih daritev ne bodo več darovali hudičem, za katerimi so se odšli vlačugat. To jim bo zakon na veke skozi njihove rodove.‹',
        8: 'Rekel jim boš: ›Katerikoli mož bo iz Izraelove hiše ali od tujcev, ki začasno prebivajo med vami, ki darujejo žgalno daritev ali žrtvovanje,',
        9: 'pa tega ne prinašajo k vratom šotorskega svetišča skupnosti, da to darujejo Gospodu; torej ta mož bo iztrebljen izmed svojega ljudstva.',
        10: 'Katerikoli človek bo tam iz Izraelove hiše ali izmed tujcev, ki začasno prebivajo med vami, ki na kakršenkoli način jé kri, bom svoj obraz naravnal prav posebej proti tej duši, ki jé kri in ga iztrebil izmed njegovih ljudi.',
        11: 'Kajti življenje mesa je v krvi in dal sem vam jo na oltarju, da opravite spravo za svoje duše, kajti kri je ta, ki opravlja spravo za dušo.',
        12: 'Zato sem Izraelovim otrokom rekel: ›Nobena duša izmed vas ne bo jedla krvi niti ne bo noben tujec, ki začasno biva med vami, jedel krvi.‹',
        13: 'Katerikoli mož bo izmed Izraelovih otrok ali od tujcev, ki začasno bivajo med vami, ki lovijo in ujamejo katerokoli žival ali perjad, ki se lahko jé, ta bo torej izlil njeno kri in jo pokril s prahom.',
        14: 'Kajti to je življenje vsega mesa, kri od tega je za njegovo življenje. Zatorej sem Izraelovim otrokom rekel: ›Na noben način ne boste jedli krvi od mesa, kajti življenje vsega mesa je njegova kri. Kdorkoli to jé, bo iztrebljen.‹',
        15: 'Vsaka duša, ki jé to, kar je poginilo samo od sebe, ali to, kar je bilo raztrgano z zvermi, bodisi je to nekdo iz vaše lastne dežele ali tujec, bo tako opral svoja oblačila kakor se okopal v vodi in bo nečist do večera. Potem bo čist.',
        16: 'Toda če jih ne opere niti ne umije svojega mesa, potem bo nosil svojo krivičnost.‹«',
    },
    18: {
        1: 'Gospod je spregovoril Mojzesu, rekoč:',
        2: '»Govori Izraelovim otrokom in jim reci: ›Jaz sem Gospod, vaš Bog.',
        3: 'Ne boste delali po ravnanjih egiptovske dežele, v kateri ste prebivali, in po ravnanjih kánaanske dežele, kamor vas vodim, ne boste delali. Niti se ne boste ravnali po njihovih odredbah.',
        4: 'Izvrševali boste moje sodbe in se držali mojih odredb, da v njih hodite. Jaz sem Gospod, vaš Bog.',
        5: 'Vi se boste torej držali mojih zakonov in mojih sodb, katere, če jih človek izvršuje, bo živel v njih. Jaz sem Gospod.',
        6: 'Nihče izmed vas se ne bo približal kateremukoli, ki mu je bližnji sorodnik, da odkrije njihovo nagoto. Jaz sem Gospod.',
        7: 'Nagote svojega očeta ali nagote svoje matere ne boš odkril. Ona je tvoja mati; ne boš odkril njene nagote.',
        8: 'Nagote žene svojega očeta ne boš odkril. To je nagota tvojega očeta.',
        9: 'Nagote svoje sestre, hčere tvojega očeta ali hčere tvoje matere, bodisi je ona rojena doma ali rojena zunaj, torej njune nagote ne boš odkril.',
        10: 'Nagote hčere svojega sina ali hčerine hčere, torej njune nagote ne boš odkril, kajti njuna je tvoja lastna nagota.',
        11: 'Nagote hčere žene tvojega očeta, rojene tvojemu očetu; ona je tvoja sestra, ne boš odkril njene nagote.',
        12: 'Ne boš odkril nagote sestre svojega očeta; ona je bližnja sorodnica tvojega očeta.',
        13: 'Ne boš odkril nagote sestre svoje matere, kajti ona je bližnja sorodnica tvoje matere.',
        14: 'Ne boš odkril nagote brata svojega očeta, ne boš se približal njegovi ženi; ona je tvoja teta.',
        15: 'Ne boš odkril nagote svoje snahe, ona je sinova žena; ne boš odkril njene nagote.',
        16: 'Ne boš odkril nagote žene svojega brata. To je nagota tvojega brata.',
        17: 'Ne boš odkril nagote ženske in njene hčere niti ne boš vzel hčere njenega sina ali hčere njene hčere, da bi odkril njeno nagoto, kajti oni sta njeni bližnji sorodnici. To je zlo.',
        18: 'Niti ne boš vzel žene k njeni sestri, da jo dražiš, da odkriješ njeno nagoto poleg druge v njenem času življenja.',
        19: 'Prav tako se ne boš približal ženski, da odkriješ njeno nagoto, dokler je oddvojena zaradi svoje nečistosti.',
        20: 'Poleg tega ne boš meseno ležal z ženo svojega soseda, da bi se z njo omadeževal.',
        21: 'Nikomur izmed svojega semena ne boš dovolil iti skozi ogenj k Molohu niti ne boš oskrunil imena svojega Boga. Jaz sem Gospod.',
        22: 'Ne boš ležal z moškimi kakor z ženskami. To je ogabnost.',
        23: 'Niti ne boš ležal z nobeno živaljo, da s tem omadežuješ samega sebe niti ne bo nobena ženska stala pred živaljo, da leže dol k njej. To je zmešnjava.',
        24: 'Ne omadežujte se z nobeno od teh stvari, kajti v vseh teh so omadeževani narodi, ki jih jaz preženem pred vami.',
        25: 'Zemlja je omadeževana, zato obiščem krivičnost le-te na njej in sama zemlja izbruha njene prebivalce.',
        26: 'Zato se boste držali mojih zakonov in mojih sodb in ne boste zagrešili nobene od teh ogabnosti; niti kdorkoli izmed vašega lastnega naroda niti katerikoli tujec, ki začasno biva med vami',
        27: '(kajti vse te ogabnosti so storili ljudje dežele, ki so bili pred vami in dežela je omadeževana),',
        28: 'da dežela tudi vas ne izpljune, ko ste jo omadeževali, kakor je izpljunila narode, ki so bili pred vami.',
        29: 'Kajti kdorkoli bo zagrešil katero izmed teh ogabnosti, celo duše, ki jih zagrešijo, bodo iztrebljene izmed svojega ljudstva.',
        30: 'Zatorej se boste držali mojih odredb, da ne zagrešite kateregakoli izmed teh gnusnih običajev, ki so bili zagrešeni pred vami in da se ne omadežujete v tem. Jaz sem Gospod, vaš Bog.‹«',
    },
    19: {
        1: 'Gospod je spregovoril Mojzesu, rekoč:',
        2: '»Spregovori vsej skupnosti Izraelovih otrok in jim reci: ›Vi bodite sveti, kajti jaz, Gospod, vaš Bog, sem svet.',
        3: '§ Bojte se vsak mož svoje matere in svojega očeta in se držite mojih šabat. Jaz sem Gospod, vaš Bog.',
        4: 'Ne obračajte se k malikom niti si ne delajte ulitih bogov. Jaz sem Gospod, vaš Bog.',
        5: 'Če darujete žrtvovanje mirovnih daritev Gospodu, jo darujte po lastni volji.',
        6: 'Jejte jo isti dan, kot jo darujete in naslednji dan. Če pa kaj ostane do tretjega dne, naj bo to sežgano v ognju.',
        7: 'Če bo karkoli pojedeno na tretji dan, je to gnusno; to ne bo sprejeto.',
        8: 'Zatorej bo vsakdo, ki to jé, nosil svojo krivičnost, ker je oskrunil posvečeno Gospodovo stvar in ta duša bo iztrebljena izmed svojega ljudstva.',
        9: 'Ko žanješ žetev svoje dežele, ne požanji v celoti vogalov svojega polja niti ne zbiraj paberkovanja svoje žetve.',
        10: 'Svojega vinograda [po trgatvi] ne boš paberkoval niti ne obiraj vsakega grozda svojega vinograda. Pusti jih za revnega in tujca. Jaz sem Gospod, vaš Bog.',
        11: 'Ne kradite, niti ne ravnajte napačno, niti ne lažite drug drugemu.',
        12: 'Pri mojem imenu ne prisegajte lažnivo niti ne skrunite imena svojega Boga. Jaz sem Gospod.',
        13: 'Svojega soseda ne goljufaj niti ga ne ropaj. Plačila tistega, ki je najet, naj ne ostanejo s teboj vso noč do jutra.',
        14: 'Ne preklinjaj gluhega niti ne polagaj kamna spotike pred slepega, temveč se boj svojega Boga. Jaz sem Gospod.',
        15: 'Na sodbi ne stori nobene nepravičnosti. Ne spoštuj revne osebe niti ne časti mogočne osebe, temveč svojega bližnjega sodi v pravičnosti.',
        16: 'Ne hodi gor in dol med svojim ljudstvom kakor tožljivec niti ne stoj zoper kri svojega bližnjega. Jaz sem Gospod.',
        17: 'V svojem srcu ne sovraži svojega brata. Vsekakor pograjaj svojega bližnjega in ne trpi greha na njem.',
        18: 'Ne maščuj se niti ne goji nobene zamere zoper otroke svojega ljudstva, temveč ljubi svojega bližnjega kakor samega sebe. Jaz sem Gospod.',
        19: 'Držite se mojih zakonov. Svoji živini ne dovoli, da se pari z različno vrsto. Svoje polje ne posej s pomešanim semenom niti naj nate ne pride obleka [hkrati] stkana iz lanu in volne.',
        20: 'Kdorkoli meseno leži z žensko, ki je sužnjica, zaročena k soprogu in sploh ni odkupljena niti ji ni dana svoboda; ona naj bo bičana. Ne bosta usmrčena, ker ona ni bila svobodna.',
        21: 'On bo k vratom šotorskega svetišča skupnosti privedel svojo daritev za prestopek Gospodu, namreč ovna za daritev za prestopek.',
        22: 'Duhovnik naj zanj pred Gospodom za njegov greh opravi spravo z ovnom daritve za prestopek, ki ga je storil, in greh, ki ga je storil, mu bo odpuščen.',
        23: 'Ko boste prišli v deželo in boste za hrano sadili vse vrste dreves, potem štejte njihov sad kot neobrezan. Tri leta vam bo ta kot neobrezan, ta naj ne bo pojeden.',
        24: 'Toda v četrtem letu bo vse njegovo sadje sveto, da s tem hvali Gospoda.',
        25: 'V petem letu boste jedli od njegovega sadja, da vam bo lahko obrodil svoj donos. Jaz sem Gospod, vaš Bog.',
        26: 'Nobene stvari ne jejte s krvjo niti ne izrekajte uroka niti ne obeležujte časov.',
        27: 'Ne zaoblite robov svojih glav niti ne kazite robov svoje brade.',
        28: 'Na svojem mesu ne boste delali nobenih urezov za mrtve niti si nase ne vtisnite nobenih znamenj. Jaz sem Gospod.',
        29: 'Ne onečasti svoje hčere, da ji ne povzročiš, da postane vlačuga, da ne bi dežela padla v vlačugarstvo in bi dežela postala polna zlobnosti.',
        30: 'Držite se mojih šabat in spoštujte moje svetišče. Jaz sem Gospod.',
        31: 'Ne obračajte se k tem, ki imajo osebne duhove niti ne povprašujte za čarovniki, da vas ne omadežujejo. Jaz sem Gospod, vaš Bog.',
        32: 'Pred osivelo glavo vstani in spoštuj obraz starca in se boj svojega Boga. Jaz sem Gospod.',
        33: 'Če tujec začasno prebiva s teboj v tvoji deželi, ga ne zatiraj.',
        34: 'Temveč naj ti bo tujec, ki prebiva s teboj, kakor nekdo rojen med vami in ljubi ga kakor samega sebe, kajti bili ste tujci v egiptovski deželi. Jaz sem Gospod, vaš Bog.',
        35: 'Nobene nepravičnosti ne delajte pri sodbi, merilni palici, teži ali meri.',
        36: 'Imejte pravične tehtnice, pravične uteži, pravičen škaf in pravičen vrč. Jaz sem Gospod, vaš Bog, ki sem vas privedel iz egiptovske dežele.',
        37: 'Zato upoštevajte vse moje zakone in vse moje sodbe ter jih izvršujte. Jaz sem Gospod.‹«',
    },
    20: {
        1: 'Gospod je spregovoril Mojzesu, rekoč:',
        2: '»Ponovno, Izraelovim otrokom boš rekel: ›Kdorkoli je izmed Izraelovih otrok ali izmed tujcev, ki začasno prebivajo v Izraelu, da izroči karkoli od svojega semena Molohu; ta bo zagotovo usmrčen. Ljudstvo dežele naj ga kamna s kamni.',
        3: 'Svoj obraz bom naravnal zoper tega človeka in ga iztrebil izmed njegovega ljudstva, ker je od svojega semena dal Molohu, da omadežuje moje svetišče in da oskruni moje sveto ime.',
        4: 'Če ljudstvo dežele kakorkoli skrije svoje oči pred možem, ko ta daje svoje seme Molohu in ga ne ubije,',
        5: 'potem bom svoj obraz naravnal zoper tega moža in zoper njegovo družino in izmed njegovega ljudstva odsekal njega in vse, ki se gredo vlačugat za njim, da bi zagrešili vlačugarstvo z Molohom.',
        6: 'Duša, ki se obrača za takšnimi, ki imajo osebne duhove in za čarovniki, da se gredo vlačugat za njimi, zoper to dušo celo naravnam svoj obraz in ga bom odsekal izmed njegovega ljudstva.',
        7: 'Posvečujte se torej in bodite sveti, kajti jaz sem Gospod, vaš Bog.',
        8: 'Držali se boste mojih zakonov in jih izvrševali. Jaz sem Gospod, ki vas posvečujem.',
        9: 'Kajti vsak, kdor preklinja svojega očeta ali svojo mater, bo zagotovo usmrčen. Preklinjal je svojega očeta ali svojo mater; njegova kri bo nad njim.',
        10: 'Moški, ki zagreši zakonolomstvo z ženo drugega moškega, torej ta, ki zagreši zakonolomstvo z ženo svojega bližnjega, zakonolomec in zakonolomka bosta zagotovo usmrčena.',
        11: 'Moški, ki leži z ženo svojega očeta, je odkril očetovo nagoto. Oba bosta zagotovo usmrčena. Njuna kri bo nad njima.',
        12: 'Če moški leži s svojo snaho, bosta zagotovo oba usmrčena. Storila sta zmešnjavo. Njuna kri naj bo nad njima.',
        13: 'Če moški leži z moškim prav tako, kakor leži z žensko, sta oba zagrešila ogabnost. Zagotovo bosta oba usmrčena. Njuna kri bo nad njima.',
        14: 'Če moški vzame ženo in njeno mater, je to zlo. Sežgani bodo z ognjem, tako on in oni dve, da tam med vami ne bo zla.',
        15: 'Če moški leži z živaljo, bo zagotovo usmrčen, žival pa boste zaklali.',
        16: 'Če se ženska približa h katerikoli živali in leže dol k njej, boš ubil žensko in žival. Obe bosta zagotovo usmrčeni. Njuna kri bo nad njima.',
        17: 'Če moški vzame svojo sestro, hčer svojega očeta ali hčer svoje matere in vidi njeno nagoto in ona vidi njegovo nagoto. To je zlobna stvar in oba bosta iztrebljena pred očmi svojega ljudstva. Odkril je nagoto svoje sestre. Nosil bo svojo krivičnost.',
        18: 'Če bo moški ležal z žensko, ki je bolna in bo odkril njeno nagoto, je odkril njen studenec in ona je odkrila studenec svoje krvi in oba izmed njiju bosta iztrebljena izmed svojega ljudstva.',
        19: 'Ne boš odkril nagote sestre svoje matere niti sestre svojega očeta, kajti on odkriva svoje bližnje sorodstvo. Oba bosta nosila svojo krivičnost.',
        20: 'Če bo moški ležal z ženo svojega strica, odkriva nagoto svojega strica. Nosila bosta svoj greh; umrla bosta brez otrok.',
        21: 'Če bo moški vzel ženo svojega brata, je to nečista stvar. Odkril je nagoto svojega brata; onadva bosta brez otrok.',
        22: 'Vi se boste torej držali vseh mojih zakonov in vseh mojih sodb in jih izvrševali, da vas dežela, kamor vas privedem, da v njej prebivate, ne izpljune.',
        23: 'Ne boste hodili po običajih naroda, ki sem ga pred vami izgnal, kajti zagrešili so vse te stvari in zato so se mi zagnusili.',
        24: 'Toda vam sem rekel: ›Podedovali boste njihovo deželo in dal vam jo bom, da jo vzamete v last, deželo kjer tečeta mleko in med.‹ Jaz sem Gospod, vaš Bog, ki vas je oddvojil od drugih ljudstev.',
        25: 'Zato boste postavili razliko med čistimi živalmi in nečistimi in med nečisto perjadjo in čisto, in svojih duš ne boste ognusili z živalmi ali s perjadjo ali s katerokoli vrsto žive stvari, ki se plazi po tleh, ki sem jo kot nečisto oddvojil od vas.',
        26: 'Vi mi boste sveti, kajti jaz, Gospod, sem svet in sem vas oddvojil od drugih ljudstev, da bi bili moji.',
        27: 'Moški ali ženska, ki ima osebnega duha ali da je čarovnik, bosta zagotovo usmrčena. Kamnajo naj ju s kamni. Njuna kri bo nad njima.‹«',
    },
    21: {
        1: 'Gospod je rekel Mojzesu: »Govori duhovnikom, Aronovim sinovom in jim reci: ›Nihče naj ne bo omadeževan zaradi mrtvega med svojim ljudstvom,',
        2: 'toda za njegove sorodnike, ki so blizu njemu, to je za njegovo mater, za njegovega očeta, za njegovega sina, za njegovo hčer, za njegovega brata',
        3: 'in za njegovo sestro devico, ki je blizu njemu, ki nima nobenega soproga; zaradi nje je lahko omadeževan.',
        4: 'Toda ta, ki je poglavar med svojim ljudstvom, sebe ne bo omadeževal, da se oskruni.',
        5: 'Ne bodo delali pleše na svoji glavi, niti ne bodo brili robov svojih brad, niti si ne bodo delali nobenih urezov na mesu.',
        6: 'Sveti bodo svojemu Bogu in ne bodo oskrunili imena svojega Boga, kajti darujejo Gospodove daritve, narejene z ognjem in kruh njihovega Boga; zato bodo sveti.',
        7: 'Naj ne vzamejo žene, ki je vlačuga ali oskrunjena niti naj ne vzamejo žene, odslovljene od njenega soproga, kajti on je svet svojemu Bogu.',
        8: 'Zato ga boš torej posvetil, kajti on daruje kruh tvojega Boga. Tebi bo svet, kajti jaz, Gospod, ki te posvečujem, sem svet.',
        9: 'Če pa se hči kateregakoli duhovnika oskruni z igranjem vlačuge, je oskrunila svojega očeta. Sežgana naj bo z ognjem.',
        10: 'Kdor je véliki duhovnik med svojimi brati, na katerega glavo je bilo izlito mazilno olje in ki je uméščen, da si nadene obleke, ne bo odkril svoje glave niti pretrgal svojih oblačil,',
        11: 'niti ne bo šel h kateremukoli truplu niti se ne bo omadeževal zaradi svojega očeta ali zaradi svoje matere,',
        12: 'niti naj ne gre ven iz svetišča niti ne oskruni svetišča svojega Boga, kajti krona mazilnega olja njegovega Boga je na njem. Jaz sem Gospod.',
        13: 'Ženo bo vzel v njenem devištvu.',
        14: 'Vdove ali ločene ženske ali oskrunjene ali pocestnice; teh ne bo vzel, temveč bo za ženo vzel devico iz svojega lastnega ljudstva.',
        15: 'Niti med svojim ljudstvom ne bo oskrunil svojega semena, kajti jaz, Gospod, ga posvečujem.‹«',
        16: 'Gospod je spregovoril Mojzesu, rekoč:',
        17: '»Govori Aronu, rekoč: ›Kdorkoli je od tvojega semena v njihovih rodovih, ki ima kakršnokoli pomanjkljivost, naj se ne približa, da bi daroval kruh svojega Boga.',
        18: 'Kajti katerikoli človek je, ki ima pomanjkljivost, se ne bo približal. Slep človek ali hrom ali kdor ima ploščat nos ali katerokoli stvar odveč',
        19: 'ali človek, ki ima zlomljeno nogo ali zlomljeno roko',
        20: 'ali je grbast ali pritlikav ali, ki ima pomanjkljivost v svojem očesu ali je grintav ali krastav ali ima zmečkana moda;',
        21: 'noben človek, ki ima iz semena duhovnika Arona pomanjkljivost, ne bo prišel blizu, da daruje Gospodove daritve narejene z ognjem. Ima pomanjkljivost; ta ne bo prišel blizu, da daruje kruh svojega Boga.',
        22: 'Jedel bo kruh svojega Boga, tako od najsvetejšega kakor od svetega.',
        23: 'Samo ta ne bo šel noter za zagrinjalo niti prišel blizu k oltarju, ker ima pomanjkljivost, da ne oskruni mojih svetišč, kajti jaz, Gospod, jih posvečujem.‹«',
        24: 'Mojzes je to povedal Aronu, njegovim sinovom in vsem Izraelovim otrokom.',
    },
    22: {
        1: 'Gospod je spregovoril Mojzesu, rekoč:',
        2: '»Govori Aronu in njegovim sinovom, da se ločijo od svetih stvari Izraelovih otrok in da ne oskrunijo mojega svetega imena v teh stvareh, ki jih posvetijo meni. Jaz sem Gospod.',
        3: 'Reci jim: ›Kdorkoli je izmed vsega vašega semena med vašimi rodovi, ki hodi k svetim stvarem, ki jih Izraelovi otroci posvetijo Gospodu in ima na sebi svojo nečistost, bo ta duša iztrebljena izpred moje prisotnosti. Jaz sem Gospod.',
        4: 'Katerikoli moški iz Aronovega semena je gobavec ali ima tekoč izliv, ta ne bo jedel od svetih stvari, dokler ne bo čist. In kdorkoli se dotakne kakršnekoli stvari, ki je nečista, pri mrtvem ali pri moškem, čigar seme gre od njega,',
        5: 'ali kdorkoli se dotika katerekoli plazeče stvari, s katero se lahko onečisti, ali človeka, od katerega lahko vzame nečistost, kakršnokoli nečistost ta ima;',
        6: 'duša, ki se je dotaknila česarkoli takega, bo nečista do večera in ne bo jedla od svetih stvari, dokler svojega mesa ne umije z vodo.',
        7: 'Ko sonce zaide bo čist in potem bo jedel od svetih stvari, ker je to njegova hrana.',
        8: 'Tega, kar pogine samo od sebe ali je raztrgano z zvermi, ne bo jedel, da samega sebe s tem omadežuje. Jaz sem Gospod.',
        9: 'Držali se bodo torej moje odredbe, da ne bi za to nosili greha in torej umrli, če to oskrunijo. Jaz, Gospod, jih posvečujem.',
        10: 'Tam noben tujec ne bo jedel od svete stvari. Duhovnikov začasni prebivalec ali najet služabnik ne bosta jedla od svete stvari.',
        11: 'Toda če duhovnik s svojim denarjem kupi katerokoli dušo, bo ta [duša] jedla od tega in kdor je rojen v njegovi hiši. Jedli bodo od njegove hrane.',
        12: 'Če pa bo duhovnikova hči poročena k tujcu, ona ne bo jedla od daritev svetih stvari.',
        13: 'Toda če je duhovnikova hči vdova ali ločena in nima otrok in je vrnjena k hiši svojega očeta kakor v svoji mladosti, bo jedla od hrane svojega očeta, toda noben tujec ne bo jedel od tega.',
        14: 'Če človek nevede jé od svete stvari, potem bo k temu dodal peti del in to bo s sveto stvarjo dal duhovniku.',
        15: 'Oni ne bodo oskrunili svetih stvari Izraelovih otrok, ki jih darujejo Gospodu',
        16: 'ali jim dopustili, da nosijo krivdo prestopka, kadar jedo njihove svete stvari, kajti jaz, Gospod, jih posvečujem.‹«',
        17: 'Gospod je spregovoril Mojzesu, rekoč:',
        18: '»Govori Aronu, njegovim sinovom in vsem Izraelovim otrokom ter jim reci: ›Kdorkoli bo od Izraelove hiše ali od tujcev v Izraelu, ki bo svoj dar daroval za vse svoje zaobljube in za vse svoje prostovoljne daritve, ki jih bodo darovali Gospodu za žgalno daritev,',
        19: 'bodo po lastni volji darovali samca brez pomanjkljivosti od goveda, od ovc ali od koz.',
        20: 'Toda karkoli ima pomanjkljivost, tega ne boste darovali, kajti to za vas ne bo sprejemljivo.',
        21: 'Kdorkoli daruje žrtvovanje mirovnih daritev Gospodu, da izpolni svojo zaobljubo ali prostovoljno daritev v govedu ali ovcah, mora biti to popolno, da bi bilo sprejeto; na tem ne bo nobene pomanjkljivosti.',
        22: 'Slepo ali zlomljeno ali pohabljeno ali kar ima rane, iz katerih se izceja ali grinto ali krasto, teh stvari ne boste darovali Gospodu niti od njih [ne boste] naredili daritve z ognjem na oltarju Gospodu.',
        23: 'Ali bikca ali jagnje, ki ima katerokoli stvar odvečno, ali karkoli manjkajočega v njegovih delih, to lahko daruješ za prostovoljno daritev, toda za zaobljubo to ne bo sprejeto.',
        24: 'Gospodu ne boste darovali tega, kar je poškodovano ali zdrobljeno ali zlomljeno ali odrezano niti v svoji deželi ne boste opravili nobenega takšnega darovanja.',
        25: 'Niti iz tujčeve roke ne boste darovali kruha svojega Boga, od kateregakoli izmed njih, ker je v njih njihova izprijenost in pomanjkljivost. Ti ne bodo sprejeti za vas.‹«',
        26: 'Gospod je spregovoril Mojzesu, rekoč:',
        27: '»Kadar je priveden bikec ali ovca ali koza, potem bo ta sedem dni pod materjo. Od osmega dne in naprej pa bo to sprejeto za ognjeno daritev Gospodu.',
        28: 'Naj bo to krava ali ovca, ne boš na isti dan zaklal nje in njenega mladega.',
        29: 'Ko boste darovali žrtev zahvaljevanja Gospodu, to darujte po lastni volji.',
        30: 'Istega dne bo to pojedeno; ničesar od tega ne boste pustili do naslednjega dne. Jaz sem Gospod.',
        31: 'Zato se boste držali mojih zapovedi in jih izpolnjevali. Jaz sem Gospod.',
        32: 'Niti ne boste oskrunili mojega svetega imena, temveč bom jaz posvečen med Izraelovim otroci. Jaz sem Gospod, ki vas posvečuje,',
        33: 'ki vas je privedel ven iz egiptovske dežele, da bi bil vaš Bog. Jaz sem Gospod.«',
    },
    23: {
        1: 'Gospod je spregovoril Mojzesu, rekoč:',
        2: '»Govori Izraelovim otrokom in jim reci: › Glede Gospodovih praznovanj, ki jih boste razglašali, da bodo sveti sklici, torej ta so moja praznovanja.',
        3: 'Šest dni naj bo delo opravljeno, toda sedmi dan je šabatni počitek, sveti sklic. Nanj ne boste opravljali nobenega dela. To je šabat Gospodu v vseh vaših prebivališčih.',
        4: 'To so Gospodova praznovanja, torej sveti sklici, ki jih boste razglašali v določenih časih.',
        5: 'Na štirinajsti dan prvega meseca zvečer je Gospodova pasha.',
        6: 'Na petnajsti dan istega meseca je praznik nekvašenega kruha Gospodu. Sedem dni morate jesti nekvašen kruh.',
        7: 'Na prvi dan boste imeli sveti sklic. Nobenega hlapčevskega dela ne boste opravljali.',
        8: 'Temveč boste sedem dni darovali ognjeno daritev Gospodu. Na sedmi dan je sveti sklic; nobenega hlapčevskega dela ne boste opravljali.‹«',
        9: 'Gospod je spregovoril Mojzesu, rekoč:',
        10: '»Govori Izraelovim otrokom in jim reci: ›Ko boste prišli v deželo, ki vam jo dam in boste poželi njeno žetev, potem boste prinesli snop prvih sadov svoje žetve duhovniku.',
        11: 'Ta bo snop majal pred Gospodom, da bo sprejet za vas. Duhovnik ga bo majal naslednji dan po šabatu.',
        12: 'Ta dan, ko boste majali snop, boste darovali jagnje brez pomanjkljivosti, prvega leta, za žgalno daritev Gospodu.',
        13: 'Jedilna daritev od tega bo dve desetinki fine moke, umešane z oljem, ognjena daritev v prijeten vonj Gospodu in jedilna daritev od tega bo četrtina vrča vina.',
        14: 'Vi pa ne boste jedli niti kruha niti popraženega zrnja niti zelenega žitnega klasja, do prav istega dne, ko svojemu Bogu prinesete dar. To bo zakon na veke skozi vaše rodove v vseh vaših prebivališčih.',
        15: 'Šteli si boste od naslednjega dne po šabatu, od dneva, ko ste prinesli snop majalne daritve; sedem šabat bo celota.',
        16: 'Torej do naslednjega dne po sedmem šabatu boste šteli petdeset dni in darovali boste novo jedilno daritev Gospodu.',
        17: 'Iz svojih prebivališč boste prinesli dva hleba majanja iz dveh desetink. Ta bosta iz fine moke; spečena bosta s kvasom. To so prvi sadovi Gospodu.',
        18: 'S kruhom boste darovali sedem enoletnih jagnjet brez pomanjkljivosti in enega mladega bikca in dva ovna. Ti bodo za žgalno daritev Gospodu, z njihovo jedilno daritvijo in njihovimi pitnimi daritvami, torej ognjeno daritvijo prijetnega vonja Gospodu.',
        19: 'Potem boste žrtvovali enega kozlička od koz za daritev za greh in dve jagnjeti prvega leta za žrtvovanje mirovnih daritev.',
        20: 'Duhovnik jih bo majal s kruhom prvih sadov za majalno daritev pred Gospodom z dvema jagnjetoma. Ti bodo sveti Gospodu za duhovnika.',
        21: 'Razglašali boste na prav isti dan, da vam bo to lahko sveti sklic. Nobenega hlapčevskega dela ne boste opravljali ta dan. To bo zakon na veke po vseh vaših prebivališčih skozi vaše rodove.',
        22: 'Ko žanjete žetev svoje dežele, med žetvijo ne boš pobral vsega do robov svojega polja niti ne boš zbiral nobenih paberkovanj svoje žetve. Pustil jih boš revnemu in tujcu. Jaz sem Gospod, vaš Bog.‹«',
        23: 'Gospod je spregovoril Mojzesu, rekoč:',
        24: '»Govori Izraelovim otrokom, rekoč: ›V sedmem mesecu, na prvi dan meseca, boste imeli šabat, spomin trobljenja trobent, sveti sklic.',
        25: 'Nobenega hlapčevskega dela ne boste opravljali ta dan, temveč boste darovali ognjeno daritev Gospodu.‹«',
        26: 'Gospod je spregovoril Mojzesu, rekoč:',
        27: '»Tudi na deseti dan tega sedmega meseca bo tam dan sprave. To vam bo sveti sklic; in ponižali boste svoje duše in darovali ognjeno daritev Gospodu.',
        28: 'Na ta isti dan ne boste delali nobenega dela, kajti to je dan sprave, da opravite spravo za vas pred Gospodom, vašim Bogom.',
        29: 'Kajti katerakoli duša bo ta, ki v tem istem dnevu ne bo ponižana, bo iztrebljena izmed svojega ljudstva.',
        30: 'Katerakoli duša bo ta, ki na ta isti dan počne kakršnokoli delo, ista duša bo uničena izmed svojega ljudstva.',
        31: 'Nobene vrste dela ne boste počeli. To bo zakon na veke skozi vaše rodove v vseh vaših prebivališčih.',
        32: 'To vam bo šabatni počitek in ponižali boste svoje duše. Na deveti dan meseca zvečer, od večera do večera, boste praznovali svoj šabat.«',
        33: 'Gospod je spregovoril Mojzesu, rekoč:',
        34: '»Govori Izraelovim otrokom, rekoč: ›Petnajsti dan sedmega meseca bo za sedem dni šotorski praznik Gospodu.',
        35: 'Na prvi dan bo sveti sklic. Nobenega hlapčevskega dela ne boste opravljali ta dan.',
        36: 'Sedem dni boste darovali ognjeno daritev Gospodu. Na osmi dan vam bo sveti sklic in darovali boste ognjeno daritev Gospodu. To je slovesen zbor in nobenega hlapčevskega dela ne boste opravljali ta dan.',
        37: 'To so Gospodovi prazniki, ki jih boste razglašali, da bodo sveti sklici, da darujete daritev, narejeno z ognjem Gospodu, žgalno daritev in jedilno daritev, žrtvovanje in pitne daritve, vsako stvar na svoj dan,',
        38: 'poleg Gospodovih šabat in poleg vaših darov in poleg vseh vaših zaobljub in poleg vseh vaših prostovoljnih daritev, ki jih izročite Gospodu.',
        39: 'Tudi na petnajsti dan sedmega meseca, ko se zberete v sadu dežele, boste sedem dni imeli praznovanje Gospodu. Na prvi dan bo šabat in na osmi dan bo šabat.',
        40: 'Na prvi dan si boste vzeli veje čednih dreves, mladike palmovih dreves, veje debelih dreves in potočnih vrb; in sedem dni se boste veselili pred Gospodom, svojim Bogom.',
        41: 'Sedem dni na leto boste ohranjali praznovanje Gospodu. To bo zakon na veke v vaših rodovih. To boste proslavljali v sedmem mesecu.',
        42: 'Sedem dni boste prebivali v šotorih; vsi, ki so rojeni Izraelci, bodo prebivali v šotorih,',
        43: 'da bodo vaši rodovi lahko vedeli, da sem Izraelovim otrokom dal prebivati v šotorih, ko sem jih privedel iz egiptovske dežele. Jaz sem Gospod, vaš Bog.‹«',
        44: 'In Mojzes je Izraelovim otrokom naznanil praznovanja Gospodu.',
    },
    24: {
        1: 'Gospod je spregovoril Mojzesu, rekoč:',
        2: '»Zapovej Izraelovim otrokom, da ti prinesejo čistega olja iz stolčenih oliv za svetlobo, da bi svetilke nenehno gorele.',
        3: 'Zunaj zagrinjala pričevanja, v šotorskem svetišču skupnosti, bo Aron to nenehno ukazoval od večera do jutra pred Gospodom. To bo zakon na veke v vaših rodovih.',
        4: 'Svetike bo nenehno oskrboval na čistem svečniku pred Gospodom.',
        5: 'Vzel boš fino moko in iz nje spekel dvanajst kolačev. Dve desetinki bosta v enem kolaču.',
        6: 'Postavil jih boš v dve vrsti, šest v vrsto, na čisto mizo pred Gospodom.',
        7: 'Nad vsako vrsto boš dal čisto kadilo, da bo ta lahko na kruhu za spomin, torej ognjena daritev Gospodu.',
        8: 'Vsak šabat ga bo nenehno postavljal v vrsto pred Gospodom, vzetega od Izraelovih otrok z večno zavezo.',
        9: 'To bo Aronovo in od njegovih sinov in to bodo jedli na svetem prostoru, kajti to mu je najsvetejše od daritev Gospodu, narejenih z ognjem, z večnim zakonom.«',
        10: 'Sin Izraelke, katere oče je bil Egipčan, je odšel ven med Izraelove otroke in ta sin izraelske ženske in mož iz Izraela sta se skupaj prepirala v taboru.',
        11: 'Sin Izraelke je izrekal bogokletje proti Gospodovemu imenu in preklinjal. Privedli so ga k Mojzesu. (In ime njegove matere je bilo Šelomíta, hči Dibríja, iz Danovega rodu.)',
        12: 'Dali so ga pod stražo, da bi jim bil lahko pokazan Gospodov um.',
        13: 'Gospod je spregovoril Mojzesu, rekoč:',
        14: '»Privedite tistega, ki je klel zunaj tabora, in naj vsi, ki so ga slišali, položijo roke na njegovo glavo in naj ga vsa skupnost kamna.',
        15: 'Izraelovim otrokom boš govoril, rekoč: ›Kdorkoli preklinja svojega Boga, bo nosil svoj greh.',
        16: 'Kdor preklinja Gospodovo ime, bo zagotovo usmrčen in zagotovo ga bo vsa skupnost kamnala; tako tujca, kakor tistega, ki je rojen v deželi, ko preklinja Gospodovo ime, bo usmrčen.',
        17: 'Kdor ubija kateregakoli človeka, bo zagotovo usmrčen.',
        18: 'Kdor ubije žival, bo to poplačal; žival za žival.',
        19: 'Če človek povzroči madež na svojem bližnjem; kakor je storil on, tako naj bo to storjeno njemu;',
        20: 'zlom za zlom, oko za oko, zob za zob. Kakor je on na človeku povzročil pomanjkljivost, tako naj bo njemu ponovno storjeno.',
        21: 'Kdor ubije žival, bo to povrnil, kdor pa ubije človeka, bo usmrčen.',
        22: 'Imeli boste eno vrsto postave, prav tako za tujca, kakor za nekoga iz svoje lastne dežele, kajti jaz sem Gospod, vaš Bog.‹«',
        23: 'Mojzes je Izraelovim otrokom spregovoril, da naj tistega, ki je preklet, privedejo ven iz tabora in kamnajo s kamni. In Izraelovi otroci so storili tako, kakor je Gospod zapovedal Mojzesu.',
    },
    25: {
        1: 'Gospod je na gori Sinaj spregovoril Mojzesu, rekoč:',
        2: '»Govori Izraelovim otrokom in jim reci: ›Ko pridete v deželo, ki sem vam jo dal, potem bo dežela ohranjala šabat Gospodu.',
        3: 'Šest let boš sejal svoje polje in šest let boš obrezoval svoj vinograd in zbiral njegov sad,',
        4: 'toda v sedmem letu bo šabatni počitek deželi, šabat za Gospoda. Niti ne boš sejal svojega polja niti obrezal svojega vinograda.',
        5: 'Tega, kar raste samo od sebe od tvoje žetve, ne boš požel niti nabiral grozdja iz svoje neobrezane trte, kajti to je za deželo leto počitka.',
        6: 'Šabatni [pridelek] dežele bo zate hrana; zate, za tvojega služabnika, za tvojo služkinjo, za tvojega najetega služabnika in za tvojega tujca, ki začasno biva s teboj',
        7: 'in ves njegov narast bo hrana za tvojo živino in za živali, ki so na tvoji zemlji.',
        8: 'Štel si boš sedem šabatnih let, sedemkrat sedem let; in obdobje sedmih šabatnih let ti bodi devetinštirideset let.',
        9: 'Potem bo šofar jubileja zadonel na deseti dan sedmega meseca. Na dan sprave boste naredili, da zvok šofarja zadoni po vsej vaši deželi.',
        10: 'Posvetili boste petdeseto leto in razglasili svobodo po vsej deželi, vsem njenim prebivalcem. To vam bo jubilej, vi pa se boste vrnili vsak mož k svoji posesti in vrnili se boste vsak mož k svoji družini.',
        11: 'Vam bo to petdeseto leto jubilej. Ne boste niti sejali niti želi tega, kar zraste samo od sebe niti nabirali grozdja v njem od vaše neobrezane trte.',
        12: 'Kajti to je jubilej; ta vam bo svet. Jedli boste njegov donos iz polja.',
        13: 'V letu tega jubileja se bo vsak človek vrnil k svoji posesti.',
        14: 'Če kaj prodaš svojemu bližnjemu, ali kaj kupiš iz roke svojega bližnjega, ne boste zatirali drug drugega.',
        15: 'Glede na število let po jubileju boš kupil od svojega bližnjega in glede na število let sadov ti bo prodal.',
        16: 'Glede na množino let boš povečal njegovo ceno in glede na manjše število let boš zmanjšal njegovo ceno, kajti glede na število let sadov ti jo bo prodal.',
        17: 'Zatorej ne boste zatirali drug drugega, temveč se boš bal svojega Boga, kajti jaz sem Gospod, tvoj Bog.',
        18: 'Zatorej boste izpolnjevali moje zakone in se držali mojih sodb in jih izvrševali, in v varnosti boste prebivali v deželi.',
        19: 'Dežela bo obrodila svoj sad in jedli boste svoje obilje in v njej varno prebivali.',
        20: 'In če boste rekli: ›Kaj bomo jedli sedmo leto? Glej, ne bomo sejali niti zbrali v našem narastu,‹',
        21: 'potem bom v šestem letu zapovedal nad vami svoj blagoslov in ta bo prinesel sad za tri leta.',
        22: 'Sejali boste osmo leto in še jedli od starih sadov do devetega leta, dokler ne pridejo njeni sadovi, boste jedli iz starih zalog.',
        23: 'Dežela naj ne bo prodana na veke, kajti dežela je moja, kajti vi ste tujci in začasni prebivalci z menoj.',
        24: 'In po vsej deželi svoje posesti boste zagotovili odkupitev za deželo.',
        25: 'Če tvoj brat postane reven in je prodal nekaj od svoje posesti in če pride katerikoli njegov sorodnik, da to odkupi, potem bo odkupil to, kar je njegov brat prodal.',
        26: 'Če mož nima nikogar, da to odkupi in je sam zmožen to odkupiti,',
        27: 'potem naj prešteje leta od njegove prodaje in povrne presežek človeku, ki mu jo je prodal, da se on lahko vrne v svojo posest.',
        28: 'Toda če mu on tega ne bo zmožen povrniti, potem bo to, kar je prodal, ostalo v roki tistega, ki je to kupil, do jubilejnega leta. Na jubilej bo odšlo in on se bo vrnil v svojo posest.',
        29: 'Če mož proda hišo za prebivanje v mestu z obzidjem, potem jo lahko odkupi znotraj celotnega leta potem, ko je bila ta prodana. Znotraj polnega leta jo lahko odkupi.',
        30: 'Če pa ta ne bo odkupljena znotraj časa polnega leta, potem bo hiša, ki je v mestu z obzidjem, utrjena na veke tistemu, ki jo je kupil, skozi vse njegove rodove. Ta v jubileju ne bo odšla.',
        31: 'Toda vaške hiše, ki naokoli nimajo obzidja, bodo štete kakor polja dežele. Lahko so odkupljene in na jubilej bodo odšle.',
        32: 'Vendar lahko mesta Lévijevcev in hiše mest njihove posesti Lévijevci kadarkoli odkupijo.',
        33: 'Če človek kupi od Lévijevcev, potem bo hiša, ki je bila prodana in mesto njegove posesti, odšlo v jubilejnem letu, kajti hiše mest Lévijevcev so njihova posest med Izraelovimi otroki.',
        34: 'Toda polje predmestij njihovih mest ne more biti prodano, kajti to je njihova neprestana posest.',
        35: 'Če tvoj brat postane reven in je zaradi tebe propadel, potem ga boš razbremenil; da, čeprav je tujec ali začasni prebivalec, da bo lahko živel s teboj.',
        36: 'Nobenih obresti ne vzemi od njega ali narasta, temveč se boj svojega Boga, da bo tvoj brat lahko živel s teboj.',
        37: 'Svojega denarja mu ne boš dal na obresti niti svojega živeža posodil za dobiček.',
        38: 'Jaz sem Gospod, vaš Bog, ki vas je privedel iz egiptovske dežele, da vam dam kánaansko deželo in, da bi bil vaš Bog.',
        39: 'Če tvoj brat, ki prebiva pri tebi, postane reven in ti je prodan, ga ne boš prisilil, da služi kakor služabnik,',
        40: 'temveč kakor najeti služabnik in kakor začasni prebivalec bo on s teboj in ti bo služil do jubilejnega leta.',
        41: 'Potem bo odšel od tebe tako on in njegovi otroci z njim in se bo vrnil k svoji lastni družini in se bo vrnil na posest svojih očetov.',
        42: 'Kajti oni so moji služabniki, ki sem jih privedel iz egiptovske dežele. Ne bodo prodani kakor tlačani.',
        43: 'Nad njim ne boš vladal s krutostjo, temveč se boš bal svojega Boga.',
        44: 'Tako tvoji služabniki in tvoje služabnice, ki jih boš imel, bodo izmed poganov, ki so naokoli vas; izmed njih si kupujte služabnike in služabnice.',
        45: 'Poleg tega izmed otrok tujcev, ki začasno prebivajo med vami, od njih boste kupovali in od njihovih družin, ki so z vami, ki so jih zaplodili v vaši deželi; in oni bodo vaša posest.',
        46: 'Vzeli jih boste kakor dediščino za svoje otroke za seboj, da jih podedujejo za posest; ti bodo vaši služabniki na veke, toda nad svojimi brati, Izraelovimi otroki, ne boste s krutostjo vladali drug nad drugim.',
        47: 'Če začasni prebivalec ali tujec poleg tebe obogati, tvoj brat, ki prebiva ob njem pa obuboža in se proda tujcu ali začasnemu prebivalcu ob tebi ali rodu tujčeve družine,',
        48: 'potem, ko je ta prodan, je lahko ponovno odkupljen. Eden izmed njegovih bratov ga lahko odkupi.',
        49: 'Odkupi ga lahko njegov stric ali sin njegovega strica ali kdorkoli, ki je blizu sorodstva njegovi družini, ga lahko odkupi, ali če je zmožen, se lahko odkupi sam.',
        50: 'Poračunal bo z njim, ki ga je kupil od leta, ko mu je bil prodan, do jubilejnega leta. Cena njegove prodaje bo glede na število let, glede na čas najetega služabnika bo ta z njim.',
        51: 'Če je zadaj še veliko let, glede na njihovo [število], bo povrnil ceno svoje odkupitve od denarja, za katerega je bil kupljen.',
        52: 'Če bo preostalo le nekaj let do jubilejnega leta, potem bo z njim obračunal in glede na njegova leta mu bo povrnil ceno njegove odkupitve.',
        53: 'In kakor letno najeti služabnik bo z njim, in drugi nad njim v tvojem pogledu ne bo vladal s krutostjo.',
        54: 'Če pa ne bo odkupljen v teh letih, potem bo odšel v jubilejnem letu, tako on in njegovi otroci z njim.',
        55: 'Kajti Izraelovi otroci so mi služabniki; oni so moji služabniki, ki sem jih privedel iz egiptovske dežele. Jaz sem Gospod, vaš Bog.‹«',
    },
    26: {
        1: '»V svoji deželi si ne boste delali nobenih malikov niti rezanih podob, niti si dvigovali stoječe podobe, niti si postavljali kakršnekoli podobe iz kamna, da bi se priklanjali k njej, kajti jaz sem Gospod, vaš Bog.',
        2: 'Držali se boste mojih šabat in spoštovali moje svetišče. Jaz sem Gospod.',
        3: 'Če se ravnate po mojih zakonih in se držite mojih zapovedi in jih izpolnjujete,',
        4: 'potem vam bom dal dež v pravšnjem obdobju in dežela bo obrodila svoj donos in poljska drevesa bodo obrodila svoj sad.',
        5: 'Vaša mlatev bo segla do trgatve in trgatev bo segla do časa setve in jedli boste svoj kruh do sitega in varno prebivali v svoji deželi.',
        6: 'V deželi bom dal mir in ulegli se boste in nihče vas ne bo prestrašil, in odstranil bom zle zveri iz dežele niti skozi vašo deželo ne bo šel meč.',
        7: 'Pregnali boste svoje sovražnike in oni bodo pred vami padli pod mečem.',
        8: 'Pet izmed vas jih bo preganjalo sto in sto izmed vas bo desettisoče pognalo v beg in vaši sovražniki bodo pred vami padli pod mečem.',
        9: 'Kajti ozrl se bom na vas in vas naredil rodovitne in vas namnožil in z vami vzpostavil svojo zavezo.',
        10: 'Jedli boste staro zalogo in staro boste zaradi nove prinesli naprej.',
        11: 'Med vami bom postavil svoje šotorsko svetišče, in moja duša vas ne bo prezirala.',
        12: 'Med vami bom hodil in bom vaš Bog in vi boste moje ljudstvo.',
        13: 'Jaz sem Gospod, vaš Bog, ki vas je privedel iz egiptovske dežele, da ne bi bili njihovi služabniki; in jaz sem zlomil vezi vašega jarma in storil, da hodite pokonci.',
        14: 'Toda če mi ne boste prisluhnili in ne boste izpolnjevali vseh teh zapovedi',
        15: 'in če boste prezirali moje zakone ali če vaša duša prezira moje sodbe, tako da ne boste izpolnjevali vseh mojih zapovedi, temveč da prelamljate mojo zavezo,',
        16: 'bom tudi jaz to storil vam; čez vas bom določil celo strahoto in uničenje in gorečo vročico, ki bo použila oči in povzročila bridkost srca, in svoje seme boste sejali zaman, kajti pojedli ga bodo vaši sovražniki.',
        17: 'Svoj obraz bom naravnal zoper vas in vi boste umorjeni pred svojimi sovražniki. Tisti, ki jih sovražite, bodo kraljevali nad vami in bežali boste, ko vas nihče ne zasleduje.',
        18: 'In če mi zaradi vsega tega še ne boste hoteli prisluhniti, potem vas bom zaradi vaših grehov sedemkrat bolj kaznoval.',
        19: 'Zlomil bom ponos vaše moči in vaše nebo bom naredil kakor železo in vašo zemljo kakor bron,',
        20: 'in vaša moč bo porabljena v prazno, kajti vaša dežela ne bo obrodila svojega donosa niti drevesa dežele ne bodo obrodila svojega sadja.',
        21: 'Če hodite nasprotno meni in mi ne boste prisluhnili, bom glede na vaše grehe nad vas privedel sedemkrat več nadlog.',
        22: 'Prav tako bom med vas poslal divje zveri, ki vas bodo oropale vaših otrok in vam uničile vašo živino in vas naredile maloštevilne, in vaše visoke poti bodo zapuščene.',
        23: 'Če ne boste po meni poboljšani s temi stvarmi, temveč boste hodili nasprotno meni,',
        24: 'potem bom tudi jaz hodil nasprotno vam in vas še sedemkrat kaznoval za vaše grehe.',
        25: 'Nad vas bom privedel meč, ki bo maščeval spor moje zaveze, in ko boste zbrani skupaj znotraj svojih mest, bom med vas poslal kužno bolezen, vi pa boste izročeni v sovražnikovo roko.',
        26: 'In ko zlomim oporo vašega kruha, bo deset žensk peklo vaš kruh v eni peči in vaš kruh vam bodo ponovno izročali po teži, in jedli boste, pa ne boste nasičeni.',
        27: 'Če mi zaradi vsega tega ne boste prisluhnili, temveč boste hodili nasprotno meni,',
        28: 'potem bom tudi jaz v razjarjenosti hodil nasprotno vam, in jaz, celo jaz, vas bom sedemkrat kaznoval za vaše grehe.',
        29: 'Jedli boste meso svojih sinov in meso svojih hčera boste jedli.',
        30: 'Uničil bom vaše visoke kraje in posekal vaše podobe in vaša trupla vrgel na trupla vaših malikov in moja duša vas bo prezirala.',
        31: 'Vaša mesta bom opustošil in vaša svetišča privedel do uničenja in ne bom vonjal vonja vaših prijetnih dišav.',
        32: 'Deželo bom privedel v opustošenje, in vaši sovražniki, ki v njej prebivajo, bodo osupli nad tem.',
        33: 'Razkropil vas bom med pogane in za vami bom izvlekel meč, in vaša dežela bo zapuščena in vaša mesta opustošena.',
        34: 'Potem bo zemlja uživala vse svoje šabate, dokler ta leži zapuščena in ste vi v deželi svojih sovražnikov, torej takrat bo dežela počivala in uživala svoje šabate.',
        35: 'Dokler ta leži zapuščena, bo počivala, ker ni počivala na vaše šabate, ko ste prebivali na njej.',
        36: 'Nad tiste, ki so izmed vas ostali živi, bom v deželi njihovih sovražnikov v njihova srca poslal slabotnost, in zvok majajočega lista jih bo pregnal; pobegnili bodo kakor bežanje pred mečem; padli bodo, ko jih nihče ne zasleduje.',
        37: 'Padli bodo drug na drugega, kakor bi bilo to pred mečem, ko nihče ne zasleduje in nobene moči ne boste imeli, da obstanete pred svojimi sovražniki.',
        38: 'Propadli boste med pogani in dežela vaših sovražnikov vas bo požrla.',
        39: 'Tisti, ki so ostali izmed vas, bodo hirali v svoji krivičnosti v deželah svojih sovražnikov in tudi v krivičnostih svojih očetov bodo hirali z njimi.',
        40: 'Če bodo priznali svojo krivičnost in krivičnost svojih očetov, s svojimi prestopki, ki so jih zagrešili zoper mene in da so tudi hodili nasprotno meni,',
        41: 'in da sem tudi jaz hodil nasprotno njim in jih privedel v deželo njihovih sovražnikov; če bodo potem njihova neobrezana srca ponižana in oni potem sprejmejo kaznovanje svoje krivičnosti,',
        42: 'potem se bom spomnil svoje zaveze z Jakobom in tudi svoje zaveze z Izakom in tudi svoje zaveze z Abrahamom se bom spomnil, in spomnil se bom dežele.',
        43: 'Tudi dežela bo od njih zapuščena in uživala bo svoje šabate, medtem ko brez njih leži zapuščena, oni pa bodo sprejeli kaznovanje svoje krivičnosti. Ker, celo ker so prezirali moje sodbe in ker je njihova duša prezirala moje zakone.',
        44: 'In kljub vsemu temu, ko bodo v deželi svojih sovražnikov, jih ne bom zavrgel niti jih ne bom preziral, da bi jih popolnoma uničil in da bi prelomil svojo zavezo z njimi, kajti jaz sem Gospod, njihov Bog.',
        45: 'Temveč se bom zaradi njih spomnil zaveze njihovih prednikov, ki sem jih privedel iz egiptovske dežele pred očmi poganov, da bi bil lahko njihov Bog. Jaz sem Gospod.«',
        46: 'To so zakoni in sodbe ter postave, ki jih je po Mojzesovi roki Gospod sklenil med njim in Izraelovimi otroki na gori Sinaj.',
    },
    27: {
        1: 'Gospod je spregovoril Mojzesu, rekoč:',
        2: '»Govori Izraelovim otrokom in jim reci: ›Kadar bo kak moški naredil edinstveno zaobljubo bodo osebe za Gospoda po tvoji oceni.',
        3: 'Tvoja ocena bo od moških od dvajset let starosti, celo do šestdesetega leta starosti, bo tvoja ocena petdeset šeklov srebra, po svetiščnem šeklu.',
        4: 'Če bo to ženska, potem bo tvoja ocena trideset šeklov.',
        5: 'Če bo ta star od petih let do dvajsetih let starosti, potem bo tvoja ocena za moškega dvajset šeklov, za žensko pa deset šeklov.',
        6: 'Če bo ta star od meseca celo do petega leta starosti, potem bo tvoja ocena za moškega pet šeklov srebra, za žensko pa bo tvoja ocena tri šekle srebra.',
        7: 'Če bo ta od šestdesetega leta starosti in navzgor; če bo to moški, potem bo tvoja ocena petnajst šeklov, za žensko pa deset šeklov.',
        8: 'Toda če je revnejši kakor tvoja ocena, potem se bo predstavil pred duhovnikom in duhovnik ga bo ocenil. Glede na svojo zmožnost, ki jo je zaobljubil, ga bo duhovnik ocenil.',
        9: 'Če bo to žival, od česar mož privede dar Gospodu, bo vse kar katerikoli človek daje od takšnega Gospodu, sveto.',
        10: 'Tega ne bo predrugačil niti spremenil, dobro za slabo ali slabo za dobro. Če bo ta sploh zamenjal žival za žival, potem postaneta ta in njena zamenjava sveti.',
        11: 'Če bo to kakršnakoli nečista žival, od katere ne darujejo daru Gospodu, potem bo žival predstavil pred duhovnikom',
        12: 'in duhovnik jo bo ocenil, naj bo ta dobra ali slaba. Kakor jo ti oceniš, ki si duhovnik, tako bo.',
        13: 'Toda če jo on sploh hoče odkupiti, potem bo tvoji oceni dodal peti del.',
        14: 'Ko bo mož svojo hišo posvetil, da bo sveta Gospodu, potem jo bo duhovnik ocenil, bodisi je dobra ali slaba. Kakor bo duhovnik to ocenil, tako bo to stalo.',
        15: 'Če bo tisti, ki jo je posvetil, odkupil svojo hišo, potem bo k njej dodal peti del denarja tvoje ocene in ta bo njegova.',
        16: 'Če bo mož posvetil Gospodu neki del od polja ali njegove posesti, potem bo tvoja ocena glede na njegovo seme. Tovor ječmenovega semena bo ocenjen za petdeset šeklov srebra.',
        17: 'Če svoje polje posveti od jubilejnega leta, glede na tvojo oceno, bo to stalo.',
        18: 'Toda če svoje polje posveti po jubileju, potem mu bo duhovnik računal denar glede na leta, ki preostanejo, celo do jubilejnega leta in to bo zmanjšano od tvoje ocene.',
        19: 'Če bo tisti, ki je polje posvetil, le-tega na kakršenkoli način odkupil, potem bo k njemu dodal peti del od denarja tvoje ocene in to mu bo zajamčeno.',
        20: 'Če pa ne bo odkupil polja ali če je polje prodal drugemu možu, le-to ne bo več odkupljeno.',
        21: 'Toda polje, ko gre le-to ven v jubileju, bo sveto Gospodu kakor posvečeno polje; njegova posest bo duhovnikova.',
        22: 'Če mož posveti Gospodu polje, ki ga je kupil, ki ni izmed polj njegove posesti,',
        23: 'potem mu bo duhovnik računal vrednost tvoje ocene, torej na jubilejno leto. In on bo dal tvojo oceno na ta dan, kakor sveto stvar Gospodu.',
        24: 'V jubilejnem letu bo polje vrnil tistemu, od katerega je bilo to kupljeno, torej tistemu, ki mu je pripadala posest dežele.',
        25: 'Vse tvoje ocene bodo glede na svetiščni šekel. Dvajset ger bo šekel.',
        26: 'Samo prvenca izmed živali, ki naj bi bil Gospodov prvenec, ne bo noben mož posvetil, bodisi je to vol ali ovca. To je Gospodovo.',
        27: 'Če pa je od nečiste živali, potem ga bo odkupil glede na tvojo oceno in bo dodal peti del od tega k temu. Ali če to ne bo odkupljeno, potem bo to prodano glede na tvojo oceno.',
        28: 'Vendar nobena posvečena stvar, ki jo mož posveti Gospodu od vsega kar ima, tako od človeka in živali in od polja njegove posesti, ne bo prodana ali odkupljena. Vsaka posvečena stvar je najsvetejša Gospodu.',
        29: 'Ničesar posvečenega, kar bo posvečeno od ljudi, ne bo odkupljeno, temveč bo zagotovo usmrčeno.',
        30: 'Vsa desetina dežele, bodisi od semena dežele ali sadu drevesa, je Gospodova. To je sveto Gospodu.',
        31: 'Če mož sploh hoče odkupiti od svojih desetin, bo temu dodal svoj peti del.',
        32: 'Glede desetine od tropa ali od črede, od česarkoli kar gre pod palico, desetina bo sveta Gospodu.',
        33: 'Ne bo iskal, če je to dobro ali slabo niti tega ne bo zamenjal. Če pa to vendar zamenja, potem bosta tako to kakor njegova zamenjava, sveta; to ne bo odkupljeno.‹«',
        34: 'To so zapovedi, ki jih je Gospod zapovedal Mojzesu za Izraelove otroke na gori Sinaj.',
    },
}
